#define RTSA_PROCESSED_FRAME_H

#include <QMetaType>
#include <QVector>
#include <cstdint>

namespace rtsa {

/// Processed frame sent from T2 (DataProcessor) to T3 (UI) via QueuedConnection.
/// Contains decimated dBm values ready for coordinate mapping by the UI widget.
struct ProcessedFrame {
    QVector<float> dBm;           // Trace 1 (Live / ClearWrite)
    QVector<float> traceMaxHold;  // Trace 2 (Max Hold)
    QVector<float> traceMinHold;  // Trace 3 (Min Hold)
    QVector<float> traceAverage;  // Trace 4 (Exponential Average)
    bool showLive     = true;
    bool showMaxHold  = false;
    bool showMinHold  = false;
    bool showAverage  = false;
    uint64_t frameId   = 0;  // frame sequence number
    uint64_t dropCount = 0;  // cumulative dropped frames
};

} // namespace rtsa

Q_DECLARE_METATYPE(rtsa::ProcessedFrame)

#endif // RTSA_PROCESSED_FRAME_H

