DataProcessor::DataProcessor(TripleBuffer<SpectrumFrame>* buffer,
                             int fftSize,
                             QObject* parent)
    : QThread(parent)
    , m_buffer(buffer)
    , m_fftSize(fftSize)
    , m_tracePipeline(fftSize)
    , m_maxHoldPipeline(fftSize)
    , m_minHoldPipeline(fftSize)
    , m_averagePipeline(fftSize)
{
    m_maxHoldPipeline.setMode(TraceMode::MaxHold);
    m_minHoldPipeline.setMode(TraceMode::MinHold);
    m_averagePipeline.setMode(TraceMode::Average);
    m_averagePipeline.setAvgCount(16);
}

void DataProcessor::stopThread()
{
    m_running = false;
    quit();
}

void DataProcessor::setTraceMode(TraceMode mode)
{
    std::lock_guard<std::mutex> lock(m_mutex);
    m_tracePipeline.setMode(mode);
}

void DataProcessor::setTraceEnabled(int traceIndex, bool enabled)
{
    std::lock_guard<std::mutex> lock(m_mutex);
    switch (traceIndex) {
    case 1: m_enableLive = enabled; break;
    case 2:
        m_enableMaxHold = enabled;
        if (enabled) m_maxHoldPipeline.reset();
        break;
    case 3:
        m_enableMinHold = enabled;
        if (enabled) m_minHoldPipeline.reset();
        break;
    case 4:
        m_enableAverage = enabled;
        if (enabled) m_averagePipeline.reset();
        break;
    default: break;
    }
}

bool DataProcessor::isTraceEnabled(int traceIndex) const
{
    std::lock_guard<std::mutex> lock(const_cast<std::mutex&>(m_mutex));
    switch (traceIndex) {
    case 1: return m_enableLive;
    case 2: return m_enableMaxHold;
    case 3: return m_enableMinHold;
    case 4: return m_enableAverage;
    default: return false;
    }
}

