void DataProcessor::processFrame(const SpectrumFrame& raw)
{
    std::lock_guard<std::mutex> lock(m_mutex);

    // Detect dropped frames
    if (m_lastFrameId > 0 && raw.frameId > m_lastFrameId + 1) {
        uint64_t dropped = raw.frameId - m_lastFrameId - 1;
        m_dropCount += dropped;
    }
    m_lastFrameId = raw.frameId;

    int count = std::min(raw.size, m_fftSize);

    // Step 1: TracePipeline processing (Live / Primary trace)
    m_tracePipeline.process(raw.data.data(), count, m_processeddBm);

    // Additional Traces if enabled
    if (m_enableMaxHold) {
        m_maxHoldPipeline.process(raw.data.data(), count, m_maxHolddBm);
    }
    if (m_enableMinHold) {
        m_minHoldPipeline.process(raw.data.data(), count, m_minHolddBm);
    }
    if (m_enableAverage) {
        m_averagePipeline.process(raw.data.data(), count, m_averagedBm);
    }

    // Step 2: Marker triggers
    if (m_pendingPeakSearch) {
        m_markerEngine.searchPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingPeakSearch = false;
    }
    if (m_pendingNextPeak) {
        m_markerEngine.searchNextPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingNextPeak = false;
    }
    if (m_pendingNextPeakRight) {
        m_markerEngine.searchNextPeakRight(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingNextPeakRight = false;
    }
    if (m_pendingNextPeakLeft) {
        m_markerEngine.searchNextPeakLeft(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingNextPeakLeft = false;
    }
    if (m_pendingMinSearch) {
        m_markerEngine.searchMin(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingMinSearch = false;
    }

    // Continuous Peak: auto-search peak every frame
    if (m_continuousPeakEnabled) {
        m_markerEngine.searchPeak(m_continuousPeakMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
    }

    // Step 3: Update existing markers
    m_markerEngine.updateMarkers(m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);

    // Step 4: Min-Max Pixel Decimation (Compress 4096 points -> 800 pixel buckets * 2 = 1600 points)
    const int targetPixels = 800;
    static std::vector<float> decimateddBm;
    static std::vector<float> decimatedMaxHold;
    static std::vector<float> decimatedMinHold;
    static std::vector<float> decimatedAverage;

    TraceDecimator::decimateMinMax(m_processeddBm.data(), count, targetPixels, decimateddBm);

    // Step 5: Prepare ProcessedFrame
    ProcessedFrame result;
    result.frameId     = raw.frameId;
    result.dropCount   = m_dropCount;
    result.showLive    = m_enableLive;
    result.showMaxHold = m_enableMaxHold;
    result.showMinHold = m_enableMinHold;
    result.showAverage = m_enableAverage;

#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
    result.dBm.assign(decimateddBm.begin(), decimateddBm.end());
#else
    result.dBm = QVector<float>::fromStdVector(decimateddBm);
#endif

    if (m_enableMaxHold && !m_maxHolddBm.empty()) {
        TraceDecimator::decimateMinMax(m_maxHolddBm.data(), count, targetPixels, decimatedMaxHold);
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
        result.traceMaxHold.assign(decimatedMaxHold.begin(), decimatedMaxHold.end());
#else
        result.traceMaxHold = QVector<float>::fromStdVector(decimatedMaxHold);
#endif
    }

    if (m_enableMinHold && !m_minHolddBm.empty()) {
        TraceDecimator::decimateMinMax(m_minHolddBm.data(), count, targetPixels, decimatedMinHold);
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
        result.traceMinHold.assign(decimatedMinHold.begin(), decimatedMinHold.end());
#else
        result.traceMinHold = QVector<float>::fromStdVector(decimatedMinHold);
#endif
    }

    if (m_enableAverage && !m_averagedBm.empty()) {
        TraceDecimator::decimateMinMax(m_averagedBm.data(), count, targetPixels, decimatedAverage);
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
        result.traceAverage.assign(decimatedAverage.begin(), decimatedAverage.end());
#else
        result.traceAverage = QVector<float>::fromStdVector(decimatedAverage);
#endif
    }

    m_processedCount++;

    emit frameReady(result);
    emit markersUpdated();
}

