#include "SpectrumPlot.h"

#include <QContextMenuEvent>
#include <QElapsedTimer>
#include <QFontMetrics>
#include <QMenu>
#include <QPaintEvent>
#include <QPainter>
#include <algorithm>
#include <cmath>
#include <map>

namespace rtsa {

// ── Keysight / R&S Style Industrial Colors ──
static const QColor kColorAppBackground(0x0a, 0x0c, 0x14);
static const QColor kColorPlotBackground(0x0e, 0x11, 0x1a);
static const QColor kColorGridMinor(0x18, 0x1e, 0x2e);
static const QColor kColorGridMajor(0x28, 0x34, 0x4c);
static const QColor kColorBorder(0x32, 0x40, 0x60);
static const QColor kColorText(0xda, 0xe2, 0xed);
static const QColor kColorTextDim(0x71, 0x80, 0x96);
static const QColor kColorAccent(0x38, 0xbd, 0xf8);

// Trace Colors
static const QColor kColorTraceLive(0x00, 0xe5, 0xff);    // Trace 1: Cyan / Neon Green
static const QColor kColorTraceMaxHold(0xff, 0xb3, 0x00); // Trace 2: Amber Yellow
static const QColor kColorTraceMinHold(0xc0, 0x84, 0xfc); // Trace 3: Lavender Purple
static const QColor kColorTraceAverage(0x38, 0xbd, 0xf8); // Trace 4: Sky Blue

SpectrumPlot::SpectrumPlot(QWidget* parent)
    : QWidget(parent)
{
    setAttribute(Qt::WA_OpaquePaintEvent);
    setMinimumSize(400, 260);
    setContextMenuPolicy(Qt::DefaultContextMenu);
    m_fpsTimer.start();
}

void SpectrumPlot::setMarkerEngine(const MarkerEngine* engine)
{
    m_markerEngine = engine;
    update();
}

// ── Parameter setters ──

void SpectrumPlot::setCenterFreq(double hz)
{
    if (qFuzzyCompare(m_centerFreq, hz)) return;
    m_centerFreq = hz;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setSpan(double hz)
{
    if (qFuzzyCompare(m_span, hz)) return;
    m_span = hz;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setRefLevel(double dBm)
{
    if (qFuzzyCompare(m_refLevel, dBm)) return;
    m_refLevel = dBm;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setDbPerDiv(double db)
{
    if (qFuzzyCompare(m_dbPerDiv, db)) return;
    m_dbPerDiv = db;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

// ── Real-time data reception from T2 ──

static void convertDbmToScreenPoints(const QVector<float>& dBmVec,
                                     const QRect& area,
                                     double refLevel,
                                     double totalRange,
                                     QVector<QPointF>& outPoints)
{
    const int count = dBmVec.size();
    if (count == 0) {
        outPoints.clear();
        return;
    }

    outPoints.resize(count);
    const double xStep = static_cast<double>(area.width()) / std::max(1, count - 1);

    for (int i = 0; i < count; ++i) {
        double x = area.left() + i * xStep;
        double yNorm = (refLevel - static_cast<double>(dBmVec[i])) / totalRange;
        double y = area.top() + yNorm * area.height();

        y = qBound(static_cast<double>(area.top()), y, static_cast<double>(area.bottom()));
        outPoints[i] = QPointF(x, y);
    }
}

void SpectrumPlot::onNewFrame(const rtsa::ProcessedFrame& frame)
{
    const QRect area = plotArea();
    if (area.width() <= 0 || area.height() <= 0) return;

    const double totalRange = m_dbPerDiv * kGridDivY;

    m_showLive    = frame.showLive;
    m_showMaxHold = frame.showMaxHold;
    m_showMinHold = frame.showMinHold;
    m_showAverage = frame.showAverage;

    if (m_showLive) {
        convertDbmToScreenPoints(frame.dBm, area, m_refLevel, totalRange, m_pointsLive);
    }
    if (m_showMaxHold) {
        convertDbmToScreenPoints(frame.traceMaxHold, area, m_refLevel, totalRange, m_pointsMaxHold);
    }
    if (m_showMinHold) {
        convertDbmToScreenPoints(frame.traceMinHold, area, m_refLevel, totalRange, m_pointsMinHold);
    }
    if (m_showAverage) {
        convertDbmToScreenPoints(frame.traceAverage, area, m_refLevel, totalRange, m_pointsAverage);
    }

    m_frameId   = frame.frameId;
    m_dropCount = frame.dropCount;

    update();
}

// ── Events ──

void SpectrumPlot::resizeEvent(QResizeEvent* event)
{
    Q_UNUSED(event)
    m_gridDirty = true;
}

void SpectrumPlot::paintEvent(QPaintEvent* event)
{
    Q_UNUSED(event)
    QElapsedTimer timer;
    timer.start();

    if (m_gridDirty) {
        rebuildGridCache();
        m_gridDirty = false;
    }

    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing, false);

    // 1. Static grid cache
    painter.drawPixmap(0, 0, m_gridCache);

    // 2. Dynamic spectrum curves
    drawCurves(painter);

    // 3. Markers & tags
    drawMarkers(painter);

    // 4. Top info bar
    drawInfoBar(painter);

    m_lastPaintTimeMs = timer.nsecsElapsed() / 1e6;
    updateFpsCounter();
}

// ── Grid Cache Construction ──

void SpectrumPlot::rebuildGridCache()
{
    m_gridCache = QPixmap(size());
    m_gridCache.fill(kColorAppBackground);

    QPainter painter(&m_gridCache);
    painter.setRenderHint(QPainter::Antialiasing, true);
    painter.setRenderHint(QPainter::TextAntialiasing, true);

    const QRect area = plotArea();

    // Fill Plot Area Background
    painter.fillRect(area, kColorPlotBackground);

    // Grid lines
    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        bool isCenter = (i == kGridDivX / 2);
        painter.setPen(QPen(isCenter ? kColorGridMajor : kColorGridMinor, 1, isCenter ? Qt::SolidLine : Qt::DashLine));
        painter.drawLine(x, area.top(), x, area.bottom());

        // X-axis tick
        painter.setPen(QPen(kColorBorder, 1));
        painter.drawLine(x, area.bottom(), x, area.bottom() + 4);
    }

    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        bool isCenter = (i == kGridDivY / 2);
        painter.setPen(QPen(isCenter ? kColorGridMajor : kColorGridMinor, 1, isCenter ? Qt::SolidLine : Qt::DashLine));
        painter.drawLine(area.left(), y, area.right(), y);

        // Y-axis tick
        painter.setPen(QPen(kColorBorder, 1));
        painter.drawLine(area.left() - 4, y, area.left(), y);
    }

    // Outer Border
    painter.setPen(QPen(kColorBorder, 1));
    painter.drawRect(area);

    // ── Y-Axis Labels ──
    painter.setFont(QFont("Consolas", 9, QFont::DemiBold));
    painter.setPen(kColorText);

    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        double dBm = m_refLevel - i * m_dbPerDiv;
        QString label = QString::number(std::round(dBm));
        QRect textRect(2, y - 8, kMarginLeft - 8, 16);
        painter.drawText(textRect, Qt::AlignRight | Qt::AlignVCenter, label);
    }

    painter.setFont(QFont("Consolas", 8, QFont::Bold));
    painter.setPen(kColorAccent);
    painter.drawText(QRect(2, area.top() - 18, kMarginLeft - 8, 16),
                     Qt::AlignRight | Qt::AlignVCenter, "dBm");

    // ── X-Axis Labels ──
    painter.setFont(QFont("Consolas", 9, QFont::DemiBold));
    painter.setPen(kColorText);

    QString unitStr = "GHz";
    double scaleDivider = 1.0e9;
    int decimals = 3;

    if (m_span < 100.0e3) {
        unitStr = "kHz";
        scaleDivider = 1.0e3;
        decimals = 2;
    } else if (m_span < 200.0e6) {
        unitStr = "MHz";
        scaleDivider = 1.0e6;
        decimals = (m_span <= 10.0e6) ? 2 : 1;
    }

    double startFreq = m_centerFreq - m_span / 2.0;
    double freqStep  = m_span / kGridDivX;

    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        double freqVal = (startFreq + i * freqStep) / scaleDivider;
        QString label = QString::number(freqVal, 'f', decimals);

        QRect textRect(x - 35, area.bottom() + 5, 70, 16);
        painter.drawText(textRect, Qt::AlignHCenter | Qt::AlignTop, label);
    }

    // X Unit tag
    painter.setFont(QFont("Consolas", 8, QFont::Bold));
    painter.setPen(kColorAccent);
    painter.drawText(QRect(area.right() - 45, area.bottom() + 22, 45, 16),
                     Qt::AlignRight | Qt::AlignVCenter, QString("[%1]").arg(unitStr));

    // Bottom Summary Bar
    painter.setFont(QFont("Consolas", 8));
    painter.setPen(kColorTextDim);
    painter.drawText(QRect(area.left(), area.bottom() + 22, area.width() - 50, 16),
                     Qt::AlignCenter,
                     QString("Start: %1   |   Center: %2   |   Stop: %3   |   Span: %4")
                         .arg(formatFrequency(startFreq))
                         .arg(formatFrequency(m_centerFreq))
                         .arg(formatFrequency(startFreq + m_span))
                         .arg(formatFrequency(m_span)));
}

// ── Draw Top Info Bar & Multi-Trace Legend ──

void SpectrumPlot::drawInfoBar(QPainter& painter)
{
    const QRect area = plotArea();

    painter.fillRect(area.left(), area.top(), area.width(), 22, QColor(0x11, 0x15, 0x22, 220));

    painter.setFont(QFont("Consolas", 9, QFont::DemiBold));

    int x = area.left() + 8;
    int y = area.top() + 2;

    // Left info
    painter.setPen(kColorText);
    painter.drawText(x, y, 160, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Ref: %1 dBm").arg(m_refLevel, 0, 'f', 1));
    painter.drawText(x + 130, y, 160, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Scale: %1 dB/div").arg(m_dbPerDiv, 0, 'f', 0));

    // Right: Multi-Trace Legend
    int legendRight = area.right() - 8;
    auto drawLegendItem = [&](const QString& name, const QColor& col) {
        QFontMetrics fm(painter.font());
        int textW = fm.horizontalAdvance(name);
        int itemW = textW + 16;
        int itemX = legendRight - itemW;

        painter.fillRect(itemX, y + 4, 10, 10, col);
        painter.setPen(kColorText);
        painter.drawText(itemX + 14, y, textW, 18, Qt::AlignLeft | Qt::AlignVCenter, name);

        legendRight -= (itemW + 10);
    };

    if (m_showAverage) drawLegendItem("Tr4:Avg", kColorTraceAverage);
    if (m_showMinHold) drawLegendItem("Tr3:Min", kColorTraceMinHold);
    if (m_showMaxHold) drawLegendItem("Tr2:Max", kColorTraceMaxHold);
    if (m_showLive)    drawLegendItem("Tr1:Live", kColorTraceLive);
}

// ── Spectrum Curves ──

void SpectrumPlot::drawCurves(QPainter& painter)
{
    const QRect area = plotArea();
    painter.setClipRect(area);
    painter.setRenderHint(QPainter::Antialiasing, true);

    // Draw Traces in order: MinHold -> Average -> MaxHold -> Live (Live on top)
    if (m_showMinHold && !m_pointsMinHold.isEmpty()) {
        painter.setPen(QPen(kColorTraceMinHold, 1.0, Qt::SolidLine));
        painter.drawPolyline(m_pointsMinHold.constData(), m_pointsMinHold.size());
    }

    if (m_showAverage && !m_pointsAverage.isEmpty()) {
        painter.setPen(QPen(kColorTraceAverage, 1.2, Qt::SolidLine));
        painter.drawPolyline(m_pointsAverage.constData(), m_pointsAverage.size());
    }

    if (m_showMaxHold && !m_pointsMaxHold.isEmpty()) {
        painter.setPen(QPen(kColorTraceMaxHold, 1.2, Qt::SolidLine));
        painter.drawPolyline(m_pointsMaxHold.constData(), m_pointsMaxHold.size());
    }

    if (m_showLive && !m_pointsLive.isEmpty()) {
        painter.setPen(QPen(kColorTraceLive, 1.2, Qt::SolidLine));
        painter.drawPolyline(m_pointsLive.constData(), m_pointsLive.size());
    }

    painter.setClipping(false);
}

// ── Markers ──

void SpectrumPlot::drawMarkers(QPainter& painter)
{
    if (!m_markerEngine) return;

    const QRect area = plotArea();
    painter.setClipRect(area);
    painter.setRenderHint(QPainter::Antialiasing, true);

    const double totalRange = m_dbPerDiv * kGridDivY;
    const double startFreq = m_centerFreq - m_span / 2.0;

    std::map<int, int> xBucketCount;

    for (const auto& m : m_markerEngine->allMarkers()) {
        if (!m.active) continue;

        double xNorm = (m.freqHz - startFreq) / m_span;
        double yNorm = (m_refLevel - m.amplitude) / totalRange;

        double x = area.left() + xNorm * area.width();
        double y = area.top() + yNorm * area.height();

        if (x < area.left() || x > area.right() || y < area.top() || y > area.bottom()) continue;

        int xBucket = static_cast<int>(x / 24);
        int overlapIndex = xBucketCount[xBucket]++;
        double yOffset = overlapIndex * 20.0;

        // Inverted triangle marker
        QPolygonF triangle;
        triangle << QPointF(x, y - yOffset)
                 << QPointF(x - 5, y - 8 - yOffset)
                 << QPointF(x + 5, y - 8 - yOffset);

        painter.setBrush(m.color);
        painter.setPen(QPen(Qt::black, 1));
        painter.drawPolygon(triangle);

        // Marker Tag Bubble
        QString tagText = QString("M%1: %2 %3dBm")
                              .arg(m.id)
                              .arg(formatFrequency(m.freqHz))
                              .arg(m.amplitude, 0, 'f', 1);
        if (m.isDelta) {
            tagText = QString("ΔM%1: %2 %3dB")
                          .arg(m.id)
                          .arg(formatFrequency(m.deltaFreqHz))
                          .arg(m.deltaAmp, 0, 'f', 1);
        }

        QFont tagFont("Consolas", 8, QFont::Bold);
        painter.setFont(tagFont);
        QFontMetrics fm(tagFont);
        int tagW = fm.horizontalAdvance(tagText) + 8;
        int tagH = 15;

        int tagX = static_cast<int>(x) - tagW / 2;
        int tagY = static_cast<int>(y - 24 - yOffset);
        tagX = qBound(area.left() + 2, tagX, area.right() - tagW - 2);

        // Tag Background
        painter.fillRect(QRect(tagX, tagY, tagW, tagH), QColor(0x0e, 0x11, 0x1a, 230));
        painter.setPen(QPen(m.color, 1));
        painter.drawRect(QRect(tagX, tagY, tagW, tagH));

        // Tag Text
        painter.setPen(m.color);
        painter.drawText(QRect(tagX, tagY, tagW, tagH), Qt::AlignCenter, tagText);
    }

    painter.setClipping(false);
}

// ── FPS Counter ──

void SpectrumPlot::updateFpsCounter()
{
    m_fpsFrameCount++;
    qint64 elapsed = m_fpsTimer.elapsed();
    if (elapsed >= 1000) {
        m_currentFps = m_fpsFrameCount * 1000.0 / elapsed;
        m_fpsFrameCount = 0;
        m_fpsTimer.restart();
    }
}

// ── Mouse Drag & Zoom Shortcuts ──

void SpectrumPlot::wheelEvent(QWheelEvent* event)
{
    int delta = event->angleDelta().y();
    if (delta == 0) return;

    double factor = (delta > 0) ? 0.8 : 1.25;
    double newSpan = std::clamp(m_span * factor, 1.0e6, 6000.0e6);

    if (std::abs(newSpan - m_span) > 1e3) {
        setSpan(newSpan);
        emit spanUserChanged(newSpan);
        event->accept();
    }
}

void SpectrumPlot::mousePressEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        QRect area = plotArea();
        if (area.contains(event->pos())) {
            m_isPlotDragging = true;
            m_dragStartPos = event->pos();
            m_dragStartCenterFreq = m_centerFreq;
            m_dragStartRefLevel   = m_refLevel;
            setCursor(Qt::ClosedHandCursor);
            event->accept();
        }
    }
}

void SpectrumPlot::mouseMoveEvent(QMouseEvent* event)
{
    m_lastMousePos = event->pos();
    if (m_isPlotDragging && (event->buttons() & Qt::LeftButton)) {
        QRect area = plotArea();
        if (area.width() <= 0 || area.height() <= 0) return;

        int dx = event->pos().x() - m_dragStartPos.x();
        int dy = event->pos().y() - m_dragStartPos.y();

        double freqPerPixel = m_span / static_cast<double>(area.width());
        double newCenterFreq = std::clamp(m_dragStartCenterFreq - dx * freqPerPixel, 10.0e6, 6000.0e6);

        double dbPerPixel = (m_dbPerDiv * kGridDivY) / static_cast<double>(area.height());
        double newRefLevel = std::clamp(m_dragStartRefLevel + dy * dbPerPixel, -120.0, 30.0);

        bool changed = false;
        if (std::abs(newCenterFreq - m_centerFreq) > 10.0) {
            setCenterFreq(newCenterFreq);
            emit centerFreqUserChanged(newCenterFreq);
            changed = true;
        }

        if (std::abs(newRefLevel - m_refLevel) > 0.1) {
            setRefLevel(newRefLevel);
            emit refLevelUserChanged(newRefLevel);
            changed = true;
        }

        if (changed) {
            event->accept();
        }
    }
}

void SpectrumPlot::mouseReleaseEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton && m_isPlotDragging) {
        m_isPlotDragging = false;
        setCursor(Qt::ArrowCursor);
        event->accept();
    }
}

// ── Right-Click Context Menu ──

void SpectrumPlot::contextMenuEvent(QContextMenuEvent* event)
{
    QRect area = plotArea();
    QMenu menu(this);
    menu.setStyleSheet(R"(
        QMenu {
            background-color: #161b26;
            color: #dae2ed;
            border: 1px solid #324060;
            padding: 4px;
            font-family: Consolas, monospace;
            font-size: 12px;
        }
        QMenu::item {
            padding: 6px 20px;
            border-radius: 3px;
        }
        QMenu::item:selected {
            background-color: #26334d;
            color: #00e5ff;
        }
        QMenu::separator {
            height: 1px;
            background-color: #324060;
            margin: 4px 6px;
        }
    )");

    // Calculate clicked frequency
    double clickedFreq = m_centerFreq;
    if (area.contains(event->pos()) && area.width() > 0) {
        double startFreq = m_centerFreq - m_span / 2.0;
        double normX = static_cast<double>(event->pos().x() - area.left()) / area.width();
        clickedFreq = startFreq + normX * m_span;
    }

    auto* actCenterHere = menu.addAction(QString("Set Center to Cursor (%1)").arg(formatFrequency(clickedFreq)));
    auto* actPeakM1     = menu.addAction("Peak Search (M1)");
    menu.addSeparator();

    auto* actZoomIn     = menu.addAction("Zoom In Span (÷2)");
    auto* actZoomOut    = menu.addAction("Zoom Out Span (×2)");
    auto* actFullSpan   = menu.addAction("Full Span (10M - 6GHz)");
    menu.addSeparator();

    auto* actResetTraces = menu.addAction("Reset All Traces");
    auto* actScreenshot  = menu.addAction("Save Screenshot (PNG)");

    QAction* selected = menu.exec(event->globalPos());
    if (!selected) return;

    if (selected == actCenterHere) {
        setCenterFreq(clickedFreq);
        emit centerFreqUserChanged(clickedFreq);
    } else if (selected == actPeakM1) {
        emit peakSearchRequested(1);
    } else if (selected == actZoomIn) {
        double newSpan = std::max(1.0e6, m_span / 2.0);
        setSpan(newSpan);
        emit spanUserChanged(newSpan);
    } else if (selected == actZoomOut) {
        double newSpan = std::min(6000.0e6, m_span * 2.0);
        setSpan(newSpan);
        emit spanUserChanged(newSpan);
    } else if (selected == actFullSpan) {
        emit fullSpanRequested();
    } else if (selected == actResetTraces) {
        emit resetTracesRequested();
    } else if (selected == actScreenshot) {
        emit screenshotRequested();
    }
}

QRect SpectrumPlot::plotArea() const
{
    return QRect(kMarginLeft, kMarginTop,
                 width() - kMarginLeft - kMarginRight,
                 height() - kMarginTop - kMarginBottom);
}

QString SpectrumPlot::formatFrequency(double hz) const
{
    double absHz = std::abs(hz);
    if (absHz >= 1e9)
        return QString("%1 GHz").arg(hz / 1e9, 0, 'f', 4);
    if (absHz >= 1e6)
        return QString("%1 MHz").arg(hz / 1e6, 0, 'f', 3);
    if (absHz >= 1e3)
        return QString("%1 kHz").arg(hz / 1e3, 0, 'f', 2);
    return QString("%1 Hz").arg(hz, 0, 'f', 0);
}

} // namespace rtsa

