static const QColor kColorTraceMaxHold(0xff, 0xb3, 0x00); // Trace 2: Amber Yellow
static const QColor kColorTraceMinHold(0xc0, 0x84, 0xfc); // Trace 3: Lavender Purple
static const QColor kColorTraceAverage(0x38, 0xbd, 0xf8); // Trace 4: Sky Blue

SpectrumPlot::SpectrumPlot(QWidget* parent)
    : QWidget(parent)
{
    setAttribute(Qt::WA_OpaquePaintEvent);
    setMinimumSize(400, 260);
    setContextMenuPolicy(Qt::DefaultContextMenu);
    m_fpsTimer.start();
}

void SpectrumPlot::setMarkerEngine(const MarkerEngine* engine)
{
    m_markerEngine = engine;
    update();
}

// ── Parameter setters ──

void SpectrumPlot::setCenterFreq(double hz)
{
    if (qFuzzyCompare(m_centerFreq, hz)) return;
    m_centerFreq = hz;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setSpan(double hz)
{
    if (qFuzzyCompare(m_span, hz)) return;
    m_span = hz;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setRefLevel(double dBm)
{
    if (qFuzzyCompare(m_refLevel, dBm)) return;
    m_refLevel = dBm;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setDbPerDiv(double db)
{
    if (qFuzzyCompare(m_dbPerDiv, db)) return;
    m_dbPerDiv = db;
    m_gridDirty = true;
