#include "SpectrumPlot.h"

#include <QElapsedTimer>
#include <QPaintEvent>
#include <QPainter>
#include <map>

namespace rtsa {

// ── Color palette ──
static const QColor kColorBackground(0x1a, 0x1a, 0x2e);
static const QColor kColorGrid(0x2d, 0x2d, 0x44);
static const QColor kColorGridMajor(0x3a, 0x3a, 0x55);
static const QColor kColorText(0xcc, 0xcc, 0xcc);
static const QColor kColorTextDim(0x88, 0x88, 0x99);
static const QColor kColorCurve(0x00, 0xff, 0x88);
static const QColor kColorInfoBar(0x22, 0x22, 0x38, 200);
static const QColor kColorAccent(0x44, 0x88, 0xff);

SpectrumPlot::SpectrumPlot(QWidget* parent)
    : QWidget(parent)
{
    setAttribute(Qt::WA_OpaquePaintEvent);
    setMinimumSize(400, 300);
    m_fpsTimer.start();

    m_markerCard = new MarkerCard(this);
}

void SpectrumPlot::setMarkerEngine(const MarkerEngine* engine)
{
    m_markerEngine = engine;
    if (m_markerCard) {
        m_markerCard->updateMarkers(m_markerEngine);
    }
    update();
}

// ── Parameter setters ──

void SpectrumPlot::setCenterFreq(double hz)
{
    if (qFuzzyCompare(m_centerFreq, hz)) return;
    m_centerFreq = hz;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setSpan(double hz)
{
    if (qFuzzyCompare(m_span, hz)) return;
    m_span = hz;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setRefLevel(double dBm)
{
    if (qFuzzyCompare(m_refLevel, dBm)) return;
    m_refLevel = dBm;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

void SpectrumPlot::setDbPerDiv(double db)
{
    if (qFuzzyCompare(m_dbPerDiv, db)) return;
    m_dbPerDiv = db;
    m_gridDirty = true;
    update();
    emit parameterChanged();
}

// ── Real-time data reception from T2 ──

void SpectrumPlot::onNewFrame(const rtsa::ProcessedFrame& frame)
{
    const QRect area = plotArea();
    if (area.width() <= 0 || area.height() <= 0) return;

    const int count = frame.dBm.size();
    if (count == 0) return;

    // Convert dBm values → screen coordinates
    m_curvePoints.resize(count);

    const double totalRange = m_dbPerDiv * kGridDivY; // total dB range on screen
    const double xStep = static_cast<double>(area.width()) / (count - 1);

    for (int i = 0; i < count; ++i) {
        double x = area.left() + i * xStep;
        double yNorm = (m_refLevel - static_cast<double>(frame.dBm[i])) / totalRange;
        double y = area.top() + yNorm * area.height();

        // Clamp to plot area
        y = qBound(static_cast<double>(area.top()),
                   y,
                   static_cast<double>(area.bottom()));

        m_curvePoints[i] = QPointF(x, y);
    }

    m_frameId   = frame.frameId;
    m_dropCount = frame.dropCount;

    update(); // schedule repaint
}

// ── Events ──

void SpectrumPlot::resizeEvent(QResizeEvent* event)
{
    Q_UNUSED(event)
    m_gridDirty = true;
}

void SpectrumPlot::paintEvent(QPaintEvent* event)
{
    Q_UNUSED(event)
    QElapsedTimer timer;
    timer.start();

    if (m_gridDirty) {
        rebuildGridCache();
        m_gridDirty = false;
    }

    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing, false);

    // Layer 1: Static grid
    painter.drawPixmap(0, 0, m_gridCache);

    // Layer 2: Dynamic spectrum curve
    drawCurve(painter);

    // Layer 3: Markers
    drawMarkers(painter);

    // Layer 4: Info bar overlay
    drawInfoBar(painter);

    m_lastPaintTimeMs = timer.nsecsElapsed() / 1e6;
    updateFpsCounter();
}

void SpectrumPlot::drawMarkers(QPainter& painter)
{
    if (!m_markerEngine) return;

    const QRect area = plotArea();
    painter.setClipRect(area);
    painter.setRenderHint(QPainter::Antialiasing, true);

    const double totalRange = m_dbPerDiv * kGridDivY;
    const double startFreq = m_centerFreq - m_span / 2.0;

    // 1. Count total active markers first for table sizing
    int activeCount = 0;
    for (const auto& m : m_markerEngine->allMarkers()) {
        if (m.active) activeCount++;
    }

    // 2. Draw Marker inverted triangles on trace
    std::map<int, int> xBucketCount;

    for (const auto& m : m_markerEngine->allMarkers()) {
        if (!m.active) continue;

        double xNorm = (m.freqHz - startFreq) / m_span;
        double yNorm = (m_refLevel - m.amplitude) / totalRange;

        double x = area.left() + xNorm * area.width();
        double y = area.top() + yNorm * area.height();

        if (x < area.left() || x > area.right() || y < area.top() || y > area.bottom()) continue;

        // Offset overlapping markers vertically
        int xBucket = static_cast<int>(x / 16);
        int overlapIndex = xBucketCount[xBucket]++;
        double yOffset = overlapIndex * 16.0;

        // Draw Marker inverted triangle
        QPolygonF triangle;
        triangle << QPointF(x, y - yOffset)
                 << QPointF(x - 6, y - 10 - yOffset)
                 << QPointF(x + 6, y - 10 - yOffset);

        painter.setBrush(m.color);
        painter.setPen(QPen(Qt::black, 1));
        painter.drawPolygon(triangle);

        // Marker label text above triangle
        painter.setFont(QFont("Consolas", 8, QFont::Bold));
        painter.setPen(m.color);

        QString text = QString("M%1").arg(m.id);
        if (m.isDelta) text = QString("ΔM%1").arg(m.id);

        painter.drawText(QRectF(x - 20, y - 24 - yOffset, 40, 14), Qt::AlignCenter, text);
    }

    painter.setClipping(false);

    // Update floating draggable MarkerCard
    if (m_markerCard) {
        m_markerCard->updateMarkers(m_markerEngine);
    }
}

// ── Grid cache ──

void SpectrumPlot::rebuildGridCache()
{
    m_gridCache = QPixmap(size());
    m_gridCache.fill(QColor(0x0e, 0x10, 0x1c)); // Deep industrial navy background

    QPainter painter(&m_gridCache);
    painter.setRenderHint(QPainter::Antialiasing, true);
    painter.setRenderHint(QPainter::TextAntialiasing, true);

    const QRect area = plotArea();

    // ── Industrial Grid Lines ──
    QColor colorGridMinor(0x1e, 0x28, 0x3c);
    QColor colorGridMajor(0x3a, 0x50, 0x70);

    // Vertical grid lines
    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        painter.setPen(QPen(i == kGridDivX / 2 ? colorGridMajor : colorGridMinor, 1, i == kGridDivX / 2 ? Qt::SolidLine : Qt::DashLine));
        painter.drawLine(x, area.top(), x, area.bottom());

        // X-axis tick mark (5px)
        painter.setPen(QPen(QColor(0x44, 0x88, 0xff), 1));
        painter.drawLine(x, area.bottom(), x, area.bottom() + 5);
    }

    // Horizontal grid lines
    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        painter.setPen(QPen(i == kGridDivY / 2 ? colorGridMajor : colorGridMinor, 1, i == kGridDivY / 2 ? Qt::SolidLine : Qt::DashLine));
        painter.drawLine(area.left(), y, area.right(), y);

        // Y-axis tick mark (5px)
        painter.setPen(QPen(QColor(0x44, 0x88, 0xff), 1));
        painter.drawLine(area.left() - 5, y, area.left(), y);
    }

    // Outer plot border box
    painter.setPen(QPen(QColor(0x44, 0x88, 0xff), 1));
    painter.drawRect(area);

    // ── Y-Axis Labels (Amplitude dBm) ──
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0x00, 0xff, 0x88)); // Industrial bright green

    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        double dBm = m_refLevel - i * m_dbPerDiv;
        QString label = QString("%1").arg(dBm, 0, 'f', 0);
        QRect textRect(2, y - 9, kMarginLeft - 10, 18);
        painter.drawText(textRect, Qt::AlignRight | Qt::AlignVCenter, label);
    }

    // Y-Axis Unit Header
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0x00, 0xe5, 0xff)); // Cyan
    painter.drawText(QRect(2, area.top() - 20, kMarginLeft - 10, 18),
                     Qt::AlignRight | Qt::AlignBottom, "dBm");

    // ── X-Axis Labels (Frequency with Dynamic Unit Scaling) ──
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0xee, 0xee, 0xff)); // High contrast readable white

    // Determine optimal unit for X-axis numbers based on Span
    QString unitStr = "GHz";
    double scaleDivider = 1.0e9;
    int decimals = 3;

    if (m_span < 100.0e3) {         // Span < 100 kHz -> Display numbers in kHz
        unitStr = "kHz";
        scaleDivider = 1.0e3;
        decimals = 2;
    } else if (m_span < 200.0e6) {  // Span < 200 MHz -> Display numbers in MHz
        unitStr = "MHz";
        scaleDivider = 1.0e6;
        decimals = (m_span <= 10.0e6) ? 2 : 1;
    } else {                       // Span >= 200 MHz -> Display numbers in GHz
        unitStr = "GHz";
        scaleDivider = 1.0e9;
        decimals = 3;
    }

    double startFreq = m_centerFreq - m_span / 2.0;
    double freqStep  = m_span / kGridDivX;

    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        double freqVal = (startFreq + i * freqStep) / scaleDivider;
        QString label = QString("%1").arg(freqVal, 0, 'f', decimals);

        QRect textRect(x - 40, area.bottom() + 6, 80, 20);
        painter.drawText(textRect, Qt::AlignHCenter | Qt::AlignTop, label);
    }

    // X-Axis Unit Header at Bottom Right
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0x00, 0xe5, 0xff));
    painter.drawText(QRect(area.right() - 60, area.bottom() + 28, 60, 18),
                     Qt::AlignRight | Qt::AlignVCenter, QString("[%1]").arg(unitStr));

    // X-Axis Sub-label (Center & Span)
    painter.drawText(QRect(area.left(), area.bottom() + 28, area.width() - 70, 18),
                     Qt::AlignCenter, QString("CENTER: %1   |   SPAN: %2")
                                          .arg(formatFrequency(m_centerFreq))
                                          .arg(formatFrequency(m_span)));
}

// ── Info bar ──

void SpectrumPlot::drawInfoBar(QPainter& painter)
{
    const QRect area = plotArea();

    painter.fillRect(area.left(), area.top(), area.width(), 24, QColor(0x16, 0x18, 0x2e));

    painter.setPen(QColor(0x00, 0xe5, 0xff));
    QFont infoFont("Consolas", 10, QFont::Bold);
    painter.setFont(infoFont);

    int x = area.left() + 10;
    int y = area.top() + 3;
    int spacing = area.width() / 5;

    painter.drawText(x, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("CF: %1").arg(formatFrequency(m_centerFreq)));

    painter.drawText(x + spacing, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Span: %1").arg(formatFrequency(m_span)));

    painter.drawText(x + spacing * 2, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Ref: %1 dBm").arg(m_refLevel, 0, 'f', 1));

    painter.drawText(x + spacing * 3, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("%1 dB/div").arg(m_dbPerDiv, 0, 'f', 0));

    // Live stats
    painter.setPen(QColor(0x88, 0xaa, 0xcc));
    painter.drawText(x + spacing * 4 - 10, y, spacing + 10, 18, Qt::AlignRight | Qt::AlignVCenter,
                     QString("%1 FPS | F#%2 D%3").arg(m_currentFps, 0, 'f', 1).arg(m_frameId).arg(m_dropCount));
}

// ── Spectrum curve ──

void SpectrumPlot::drawCurve(QPainter& painter)
{
    if (m_curvePoints.isEmpty()) return;

    QPen curvePen(kColorCurve, 1, Qt::SolidLine);
    painter.setPen(curvePen);
    painter.setClipRect(plotArea());

    painter.drawPolyline(m_curvePoints.constData(), m_curvePoints.size());

    painter.setClipping(false);
}

// ── FPS counter ──

void SpectrumPlot::updateFpsCounter()
{
    m_fpsFrameCount++;
    qint64 elapsed = m_fpsTimer.elapsed();
    if (elapsed >= 1000) {
        m_currentFps = m_fpsFrameCount * 1000.0 / elapsed;
        m_fpsFrameCount = 0;
        m_fpsTimer.restart();
    }
}

// ── Helpers ──

// ── Mouse Drag & Wheel Shortcuts ──

void SpectrumPlot::wheelEvent(QWheelEvent* event)
{
    int delta = event->angleDelta().y();
    if (delta == 0) return;

    double factor = (delta > 0) ? 0.85 : 1.18;
    double newSpan = std::clamp(m_span * factor, 1.0e6, 1000.0e6);

    if (std::abs(newSpan - m_span) > 1e3) {
        setSpan(newSpan);
        emit spanUserChanged(newSpan);
        event->accept();
    }
}

void SpectrumPlot::mousePressEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        QRect area = plotArea();
        if (area.contains(event->pos())) {
            m_isPlotDragging = true;
            m_dragStartPos = event->pos();
            m_dragStartCenterFreq = m_centerFreq;
            m_dragStartRefLevel   = m_refLevel;
            setCursor(Qt::ClosedHandCursor);
            event->accept();
        }
    }
}

void SpectrumPlot::mouseMoveEvent(QMouseEvent* event)
{
    if (m_isPlotDragging && (event->buttons() & Qt::LeftButton)) {
        QRect area = plotArea();
        if (area.width() <= 0 || area.height() <= 0) return;

        int dx = event->pos().x() - m_dragStartPos.x();
        int dy = event->pos().y() - m_dragStartPos.y();

        // Horizontal Drag -> Shift Center Frequency
        double freqPerPixel = m_span / static_cast<double>(area.width());
        double newCenterFreq = std::clamp(m_dragStartCenterFreq - dx * freqPerPixel, 10.0e6, 6000.0e6);

        // Vertical Drag -> Shift Ref Level
        double dbPerPixel = (m_dbPerDiv * kGridDivY) / static_cast<double>(area.height());
        double newRefLevel = std::clamp(m_dragStartRefLevel + dy * dbPerPixel, -120.0, 30.0);

        bool changed = false;
        if (std::abs(newCenterFreq - m_centerFreq) > 10.0) {
            setCenterFreq(newCenterFreq);
            emit centerFreqUserChanged(newCenterFreq);
            changed = true;
        }

        if (std::abs(newRefLevel - m_refLevel) > 0.1) {
            setRefLevel(newRefLevel);
            emit refLevelUserChanged(newRefLevel);
            changed = true;
        }

        if (changed) {
            event->accept();
        }
    }
}

void SpectrumPlot::mouseReleaseEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton && m_isPlotDragging) {
        m_isPlotDragging = false;
        setCursor(Qt::ArrowCursor);
        event->accept();
    }
}

QRect SpectrumPlot::plotArea() const
{
    return QRect(kMarginLeft, kMarginTop,
                 width() - kMarginLeft - kMarginRight,
                 height() - kMarginTop - kMarginBottom);
}

QString SpectrumPlot::formatFrequency(double hz) const
{
    if (hz >= 1e9)
        return QString("%1 G").arg(hz / 1e9, 0, 'f', 3);
    if (hz >= 1e6)
        return QString("%1 M").arg(hz / 1e6, 0, 'f', 2);
    if (hz >= 1e3)
        return QString("%1 k").arg(hz / 1e3, 0, 'f', 1);
    return QString("%1 Hz").arg(hz, 0, 'f', 0);
}

