#ifndef RTSA_TOP_BAR_WIDGET_H
#define RTSA_TOP_BAR_WIDGET_H

#include <QWidget>
#include <QLabel>
#include <QPushButton>

namespace rtsa {

enum class RunState {
    Running,
    Single,
    Stopped
};

class TopBarWidget : public QWidget {
    Q_OBJECT

public:
    explicit TopBarWidget(QWidget* parent = nullptr);

    void setRunState(RunState state);
    RunState runState() const { return m_runState; }

    void setRtbw(double hz);
    void setRbw(double hz);
    void setFps(double fps);
    void setFftRate(const QString& rateStr);
    void setPoi(const QString& poiStr);

signals:
    void runRequested();
    void singleRequested();
    void stopRequested();

private:
    void updateButtonStyles();

    RunState m_runState = RunState::Running;

    QPushButton* m_btnRun    = nullptr;
    QPushButton* m_btnSingle = nullptr;
    QPushButton* m_btnStop   = nullptr;

    QLabel* m_titleLabel  = nullptr;
    QLabel* m_deviceLabel = nullptr;
    QLabel* m_rtbwLabel   = nullptr;
    QLabel* m_rbwLabel    = nullptr;
    QLabel* m_poiLabel    = nullptr;
    QLabel* m_fftLabel    = nullptr;
    QLabel* m_fpsLabel    = nullptr;
};

} // namespace rtsa

#endif // RTSA_TOP_BAR_WIDGET_H

#include "TopBarWidget.h"

#include <QHBoxLayout>
#include <QFrame>

namespace rtsa {

TopBarWidget::TopBarWidget(QWidget* parent)
    : QWidget(parent)
{
    setFixedHeight(38);
    setObjectName("TopBarWidget");
    setStyleSheet(R"(
        QWidget#TopBarWidget {
            background-color: #121520;
            border-bottom: 1px solid #283248;
        }
        QLabel {
            color: #94a3b8;
            font-family: Consolas, monospace;
            font-size: 11px;
        }
        QLabel#Title {
            color: #00e5ff;
            font-size: 13px;
            font-weight: bold;
            letter-spacing: 0.5px;
        }
        QLabel#DeviceTag {
            color: #10b981;
            background-color: #064e3b;
            border: 1px solid #059669;
            border-radius: 3px;
            padding: 2px 6px;
            font-weight: bold;
            font-size: 10px;
        }
        QLabel.stat-val {
            color: #e2e8f0;
            font-weight: bold;
        }
        QPushButton {
            font-family: Consolas, monospace;
            font-size: 11px;
            font-weight: bold;
            border-radius: 3px;
            padding: 3px 10px;
            min-height: 22px;
        }
    )");

    auto* layout = new QHBoxLayout(this);
    layout->setContentsMargins(10, 4, 10, 4);
    layout->setSpacing(8);

    // ── Acquisition Controls (RUN / SINGLE / STOP) ──
    m_btnRun = new QPushButton("● RUN", this);
    m_btnSingle = new QPushButton("❚❚ SINGLE", this);
    m_btnStop = new QPushButton("■ STOP", this);

