    connect(m_btnSingle, &QPushButton::clicked, this, &TopBarWidget::singleRequested);
    connect(m_btnStop, &QPushButton::clicked, this, &TopBarWidget::stopRequested);

    layout->addWidget(m_btnRun);
    layout->addWidget(m_btnSingle);
    layout->addWidget(m_btnStop);

    auto* sep1 = new QFrame(this);
    sep1->setFrameShape(QFrame::VLine);
    sep1->setStyleSheet("color: #283248;");
    layout->addWidget(sep1);

    // ── Application Title & Device Indicator ──
    m_titleLabel = new QLabel("RTSA-X Real-Time Signal Analyzer", this);
    m_titleLabel->setObjectName("Title");
    layout->addWidget(m_titleLabel);

    m_deviceLabel = new QLabel("● RFSoC Live", this);
