namespace rtsa {

BottomParamBar::BottomParamBar(QWidget* parent)
    : QWidget(parent)
{
    setFixedHeight(42);
    setObjectName("BottomParamBar");
    setStyleSheet(R"(
        QWidget#BottomParamBar {
            background-color: #121520;
            border-top: 1px solid #283248;
        }
        QLabel {
            color: #94a3b8;
            font-family: Consolas, monospace;
            font-size: 11px;
            font-weight: bold;
        }
        QDoubleSpinBox {
            background-color: #181d2a;
            color: #00e5ff;
            font-family: Consolas, monospace;
            font-size: 11px;
            font-weight: bold;
            border: 1px solid #334155;
            border-radius: 3px;
            padding: 3px 6px;
            min-height: 22px;
        }
        QDoubleSpinBox:focus {
            border-color: #00e5ff;
            background-color: #1e2538;
        }
        QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
            width: 14px;
            background: #242c3e;
            border: none;
        }
        QDoubleSpinBox::up-button:hover, QDoubleSpinBox::down-button:hover {
            background: #38bdf8;
        }
    )");

    auto* layout = new QHBoxLayout(this);
    layout->setContentsMargins(10, 4, 10, 4);
    layout->setSpacing(10);

    auto createParamItem = [this, layout](const QString& labelText, double minVal, double maxVal, double step, const QString& suffix, int decimals = 3) -> QDoubleSpinBox* {
        auto* label = new QLabel(labelText, this);
        auto* spin = new QDoubleSpinBox(this);
        spin->setRange(minVal, maxVal);
        spin->setSingleStep(step);
        spin->setSuffix(" " + suffix);
        spin->setDecimals(decimals);
        spin->setKeyboardTracking(false);

        layout->addWidget(label);
        layout->addWidget(spin);
        return spin;
    };

    // ── Frequency Domain Group ──
    m_spinCenter = createParamItem("CENTER:", 10.0, 6000.0, 10.0, "MHz", 3);
    m_spinSpan   = createParamItem("SPAN:", 1.0, 6000.0, 10.0, "MHz", 3);

    auto* sep1 = new QFrame(this);
    sep1->setFrameShape(QFrame::VLine);
    sep1->setStyleSheet("color: #283248;");
    layout->addWidget(sep1);

    m_spinStart  = createParamItem("START:", 10.0, 6000.0, 10.0, "MHz", 3);
    m_spinStop   = createParamItem("STOP:", 10.0, 6000.0, 10.0, "MHz", 3);

    auto* sep2 = new QFrame(this);
    sep2->setFrameShape(QFrame::VLine);
    sep2->setStyleSheet("color: #283248;");
    layout->addWidget(sep2);

    // ── Amplitude Domain Group ──
    m_spinRef    = createParamItem("REF LEVEL:", -120.0, 30.0, 5.0, "dBm", 1);
    m_spinScale  = createParamItem("SCALE:", 1.0, 20.0, 1.0, "dB/div", 0);

    layout->addStretch(1);

    // Connections
    connect(m_spinCenter, QOverload<double>::of(&QDoubleSpinBox::valueChanged), this, &BottomParamBar::onCenterEdited);
    connect(m_spinSpan, QOverload<double>::of(&QDoubleSpinBox::valueChanged), this, &BottomParamBar::onSpanEdited);
    connect(m_spinStart, QOverload<double>::of(&QDoubleSpinBox::valueChanged), this, &BottomParamBar::onStartEdited);
    connect(m_spinStop, QOverload<double>::of(&QDoubleSpinBox::valueChanged), this, &BottomParamBar::onStopEdited);
    connect(m_spinRef, QOverload<double>::of(&QDoubleSpinBox::valueChanged), this, &BottomParamBar::onRefEdited);
    connect(m_spinScale, QOverload<double>::of(&QDoubleSpinBox::valueChanged), this, &BottomParamBar::onScaleEdited);

    updateDisplays();
}

void BottomParamBar::setCenterFreq(double hz)
{
    if (std::abs(m_centerFreq - hz) < 1.0) return;
    m_centerFreq = hz;
    updateDisplays();
}

void BottomParamBar::setSpan(double hz)
{
    if (std::abs(m_span - hz) < 1.0) return;
    m_span = hz;
    updateDisplays();
}

void BottomParamBar::setRefLevel(double dBm)
{
    if (std::abs(m_refLevel - dBm) < 0.05) return;
    m_refLevel = dBm;
    updateDisplays();
}

void BottomParamBar::setScale(double dbPerDiv)
{
    if (std::abs(m_scale - dbPerDiv) < 0.05) return;
    m_scale = dbPerDiv;
    updateDisplays();
}

void BottomParamBar::updateDisplays()
{
    m_updating = true;

    double centerMHz = m_centerFreq / 1.0e6;
    double spanMHz   = m_span / 1.0e6;
    double startMHz  = (m_centerFreq - m_span / 2.0) / 1.0e6;
    double stopMHz   = (m_centerFreq + m_span / 2.0) / 1.0e6;

    m_spinCenter->setValue(centerMHz);
    m_spinSpan->setValue(spanMHz);
    m_spinStart->setValue(startMHz);
    m_spinStop->setValue(stopMHz);
    m_spinRef->setValue(m_refLevel);
    m_spinScale->setValue(m_scale);

    m_updating = false;
}

void BottomParamBar::onCenterEdited()
{
    if (m_updating) return;
    double newCenterHz = m_spinCenter->value() * 1.0e6;
    m_centerFreq = newCenterHz;
    updateDisplays();
    emit centerFreqChanged(m_centerFreq);
}

void BottomParamBar::onSpanEdited()
{
    if (m_updating) return;
    double newSpanHz = m_spinSpan->value() * 1.0e6;
    m_span = newSpanHz;
    updateDisplays();
    emit spanChanged(m_span);
}

void BottomParamBar::onStartEdited()
{
    if (m_updating) return;
    double startMHz = m_spinStart->value();
    double stopMHz  = m_spinStop->value();

    if (startMHz >= stopMHz) {
        startMHz = stopMHz - 1.0;
    }

    double newCenterHz = ((startMHz + stopMHz) / 2.0) * 1.0e6;
    double newSpanHz   = (stopMHz - startMHz) * 1.0e6;

    m_centerFreq = newCenterHz;
    m_span       = newSpanHz;

    updateDisplays();
    emit centerFreqChanged(m_centerFreq);
    emit spanChanged(m_span);
}

void BottomParamBar::onStopEdited()
{
    if (m_updating) return;
    double startMHz = m_spinStart->value();
    double stopMHz  = m_spinStop->value();

    if (stopMHz <= startMHz) {
        stopMHz = startMHz + 1.0;
    }

    double newCenterHz = ((startMHz + stopMHz) / 2.0) * 1.0e6;
    double newSpanHz   = (stopMHz - startMHz) * 1.0e6;

    m_centerFreq = newCenterHz;
    m_span       = newSpanHz;

    updateDisplays();
    emit centerFreqChanged(m_centerFreq);
    emit spanChanged(m_span);
}

void BottomParamBar::onRefEdited()
{
    if (m_updating) return;
    m_refLevel = m_spinRef->value();
    emit refLevelChanged(m_refLevel);
}

void BottomParamBar::onScaleEdited()
{
    if (m_updating) return;
    m_scale = m_spinScale->value();
    emit scaleChanged(m_scale);
}

