    : QWidget(parent)
{
    setFixedHeight(84);
    setObjectName("MarkerTableWidget");
    setStyleSheet(R"(
        QWidget#MarkerTableWidget {
            background-color: #0e111a;
            border-top: 1px solid #283248;
        }
        QTableWidget {
            background-color: #0e111a;
