void MarkerTableWidget::initTable()
{
    m_table = new QTableWidget(this);
    m_table->setColumnCount(7);
    m_table->setRowCount(6);

    QStringList headers = {"Marker", "Active", "Type", "Frequency", "Amplitude", "Δ Freq", "Δ Amp"};
    m_table->setHorizontalHeaderLabels(headers);
    m_table->verticalHeader()->setVisible(false);
    m_table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);
    m_table->horizontalHeader()->setSectionResizeMode(0, QHeaderView::ResizeToContents);
    m_table->horizontalHeader()->setSectionResizeMode(1, QHeaderView::ResizeToContents);
    m_table->horizontalHeader()->setSectionResizeMode(2, QHeaderView::ResizeToContents);

    m_table->setSelectionBehavior(QAbstractItemView::SelectRows);
    m_table->setSelectionMode(QAbstractItemView::SingleSelection);
    m_table->setEditTriggers(QAbstractItemView::NoEditTriggers);

    // Initial placeholder rows
    for (int i = 0; i < 6; ++i) {
        int id = i + 1;
        auto* itemM = new QTableWidgetItem(QString("M%1").arg(id));
        itemM->setTextAlignment(Qt::AlignCenter);
        itemM->setFont(QFont("Consolas", 10, QFont::Bold));

        auto* itemAct = new QTableWidgetItem("OFF");
        itemAct->setTextAlignment(Qt::AlignCenter);

        auto* itemType = new QTableWidgetItem("Normal");
        itemType->setTextAlignment(Qt::AlignCenter);

        auto* itemFreq = new QTableWidgetItem("---");
        itemFreq->setTextAlignment(Qt::AlignCenter);

        auto* itemAmp = new QTableWidgetItem("---");
        itemAmp->setTextAlignment(Qt::AlignCenter);

        auto* itemDeltaF = new QTableWidgetItem("---");
        itemDeltaF->setTextAlignment(Qt::AlignCenter);

        auto* itemDeltaA = new QTableWidgetItem("---");
        itemDeltaA->setTextAlignment(Qt::AlignCenter);

        m_table->setItem(i, 0, itemM);
        m_table->setItem(i, 1, itemAct);
        m_table->setItem(i, 2, itemType);
        m_table->setItem(i, 3, itemFreq);
        m_table->setItem(i, 4, itemAmp);
        m_table->setItem(i, 5, itemDeltaF);
        m_table->setItem(i, 6, itemDeltaA);
        m_table->setRowHeight(i, 20);
    }

    connect(m_table, &QTableWidget::cellClicked, [this](int row, int /*col*/) {
        emit markerSelected(row + 1);
    });
}

static QString formatFreqStr(double hz)
{
    double absHz = std::abs(hz);
    if (absHz >= 1e9)
        return QString("%1 GHz").arg(hz / 1e9, 0, 'f', 6);
    if (absHz >= 1e6)
        return QString("%1 MHz").arg(hz / 1e6, 0, 'f', 4);
    if (absHz >= 1e3)
        return QString("%1 kHz").arg(hz / 1e3, 0, 'f', 2);
    return QString("%1 Hz").arg(hz, 0, 'f', 0);
}

void MarkerTableWidget::updateMarkers(const MarkerEngine* engine)
{
    if (!engine || !m_table) return;

    m_updating = true;

    for (int i = 0; i < 6; ++i) {
        int id = i + 1;
        const auto& m = engine->marker(id);

        auto* itemM = m_table->item(i, 0);
        auto* itemAct = m_table->item(i, 1);
        auto* itemType = m_table->item(i, 2);
        auto* itemFreq = m_table->item(i, 3);
        auto* itemAmp = m_table->item(i, 4);
        auto* itemDeltaF = m_table->item(i, 5);
        auto* itemDeltaA = m_table->item(i, 6);

        if (itemM) {
            itemM->setForeground(m.color);
        }

        if (m.active) {
            if (itemAct) {
                itemAct->setText("ON");
                itemAct->setForeground(QColor(0x10, 0xb9, 0x81)); // Green
            }
            if (itemType) {
                itemType->setText(m.isDelta ? "Delta" : "Normal");
                itemType->setForeground(m.isDelta ? QColor(0x38, 0xbd, 0xf8) : QColor(0xda, 0xe2, 0xed));
            }
            if (itemFreq) {
                itemFreq->setText(formatFreqStr(m.freqHz));
                itemFreq->setForeground(QColor(0x00, 0xe5, 0xff));
            }
            if (itemAmp) {
                itemAmp->setText(QString("%1 dBm").arg(m.amplitude, 0, 'f', 2));
                itemAmp->setForeground(QColor(0xda, 0xe2, 0xed));
            }
            if (itemDeltaF) {
                if (m.isDelta) {
                    itemDeltaF->setText(formatFreqStr(m.deltaFreqHz));
                    itemDeltaF->setForeground(QColor(0x38, 0xbd, 0xf8));
                } else {
                    itemDeltaF->setText("---");
                    itemDeltaF->setForeground(QColor(0x64, 0x74, 0x8b));
                }
            }
            if (itemDeltaA) {
                if (m.isDelta) {
                    itemDeltaA->setText(QString("%1 dB").arg(m.deltaAmp, 0, 'f', 2));
                    itemDeltaA->setForeground(QColor(0x38, 0xbd, 0xf8));
                } else {
                    itemDeltaA->setText("---");
                    itemDeltaA->setForeground(QColor(0x64, 0x74, 0x8b));
                }
            }
        } else {
            if (itemAct) {
                itemAct->setText("OFF");
                itemAct->setForeground(QColor(0x64, 0x74, 0x8b));
            }
            if (itemType) {
                itemType->setText("---");
                itemType->setForeground(QColor(0x64, 0x74, 0x8b));
            }
            if (itemFreq) {
                itemFreq->setText("---");
                itemFreq->setForeground(QColor(0x64, 0x74, 0x8b));
            }
            if (itemAmp) {
                itemAmp->setText("---");
                itemAmp->setForeground(QColor(0x64, 0x74, 0x8b));
            }
            if (itemDeltaF) {
                itemDeltaF->setText("---");
                itemDeltaF->setForeground(QColor(0x64, 0x74, 0x8b));
            }
            if (itemDeltaA) {
                itemDeltaA->setText("---");
                itemDeltaA->setForeground(QColor(0x64, 0x74, 0x8b));
            }
        }
    }

    m_updating = false;
}

