#ifndef RTSA_CONTROL_PANEL_H
#define RTSA_CONTROL_PANEL_H

#include "TracePipeline.h"
#include <QWidget>
#include <QPushButton>
#include <QComboBox>
#include <QCheckBox>
#include <QLabel>
#include <QTabWidget>

namespace rtsa {

/// Compact Tabbed Analysis & Control Panel (Keysight / R&S Style)
class ControlPanel : public QWidget {
    Q_OBJECT

public:
    explicit ControlPanel(QWidget* parent = nullptr);

    void setStatus(const QString& status);
    void setFps(double fps);
    void setRbw(double hz);
    void setCenterFreq(double hz);
    void setSpan(double hz);
    void setRefLevel(double dBm);

signals:
    // Trace Multi-Channel Controls
    void traceToggled(int traceIndex, bool enabled);
    void resetAllTracesRequested();

    // Marker Controls
    void markerSelected(int markerId);
    void peakSearchRequested(int markerId);
    void nextPeakRequested(int markerId);
    void peakRightRequested(int markerId);
    void peakLeftRequested(int markerId);
    void minSearchRequested(int markerId);
    void globalDeltaToggled(bool enable, int refMarkerId);
    void clearAllMarkersRequested();
    void continuousPeakToggled(bool enabled, int markerId);

    // Display & Export
    void spectrogramToggled(bool show);
    void fullSpanRequested();
    void exportCsvRequested();
    void saveScreenshotRequested();

private:
    void setupMarkerTab(QWidget* tab);
    void setupTraceTab(QWidget* tab);
    void setupDisplayTab(QWidget* tab);
    void setupExportTab(QWidget* tab);

    QTabWidget* m_tabWidget = nullptr;

    // Marker Tab Widgets
    QComboBox* m_markerSelectCombo = nullptr;
    QPushButton* m_btnPeakSearch = nullptr;
    QPushButton* m_btnNextPeak = nullptr;
    QPushButton* m_btnPeakLeft = nullptr;
    QPushButton* m_btnPeakRight = nullptr;
    QPushButton* m_btnMinSearch = nullptr;
    QPushButton* m_btnContinuousPeak = nullptr;
    QPushButton* m_btnDeltaToggle = nullptr;
    QPushButton* m_btnClearMarkers = nullptr;

    // Trace Tab Widgets
    QCheckBox* m_chkTrace1 = nullptr;
    QCheckBox* m_chkTrace2 = nullptr;
    QCheckBox* m_chkTrace3 = nullptr;
    QCheckBox* m_chkTrace4 = nullptr;
    QPushButton* m_btnResetTraces = nullptr;

    // Display Tab Widgets
    QPushButton* m_btnSpectrogramToggle = nullptr;
    QPushButton* m_btnFullSpan = nullptr;

    // Export Tab Widgets
    QPushButton* m_btnExportCsv = nullptr;
    QPushButton* m_btnSaveScreenshot = nullptr;

    bool m_isDeltaActive = false;
    bool m_isSpectrogramActive = false;
    bool m_isContinuousPeakActive = false;
};

} // namespace rtsa

#endif // RTSA_CONTROL_PANEL_H

