#include "ControlPanel.h"

#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QGridLayout>
#include <QGroupBox>
#include <QPalette>

namespace rtsa {

static const QString kTabStyleSheet = R"(
    QWidget#ControlPanel {
        background-color: #121520;
        border-left: 1px solid #283248;
    }
    QTabWidget::pane {
        border: 1px solid #283248;
        background-color: #161b28;
        border-radius: 4px;
        top: -1px;
    }
    QTabBar::tab {
        background-color: #121520;
        color: #94a3b8;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        padding: 6px 10px;
        border: 1px solid #283248;
        border-bottom: none;
        border-top-left-radius: 4px;
        border-top-right-radius: 4px;
        margin-right: 2px;
    }
    QTabBar::tab:selected {
        background-color: #161b28;
        color: #00e5ff;
        border-bottom: 1px solid #161b28;
    }
    QTabBar::tab:hover:!selected {
        background-color: #1e2538;
        color: #e2e8f0;
    }
    QLabel {
        color: #94a3b8;
        font-family: Consolas, monospace;
        font-size: 11px;
    }
    QComboBox {
        background-color: #1a2030;
        color: #00e5ff;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        border: 1px solid #334155;
        border-radius: 3px;
        padding: 4px 6px;
        min-height: 22px;
    }
    QComboBox::drop-down {
        border: none;
        width: 18px;
    }
    QComboBox QAbstractItemView {
        background-color: #1a2030;
        color: #00e5ff;
        selection-background-color: #2e3850;
        selection-color: #ffffff;
    }
    QCheckBox {
        color: #e2e8f0;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        spacing: 6px;
    }
    QCheckBox::indicator {
        width: 14px;
        height: 14px;
        border: 1px solid #475569;
        border-radius: 2px;
        background-color: #1a2030;
    }
    QCheckBox::indicator:checked {
        background-color: #00e5ff;
        border-color: #00e5ff;
    }
    QPushButton {
        background-color: #1e2538;
        color: #e2e8f0;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        border: 1px solid #334155;
        border-radius: 3px;
        padding: 5px 8px;
        min-height: 22px;
    }
    QPushButton:hover {
        background-color: #283248;
        border-color: #00e5ff;
        color: #ffffff;
    }
    QPushButton:pressed {
        background-color: #00e5ff;
        color: #0a0c14;
    }
    QPushButton#BtnExport {
        background-color: #064e3b;
        color: #10b981;
        border-color: #059669;
    }
    QPushButton#BtnExport:hover {
        background-color: #059669;
        color: #ffffff;
    }
)";

ControlPanel::ControlPanel(QWidget* parent)
    : QWidget(parent)
{
    setObjectName("ControlPanel");
    setFixedWidth(240);
    setStyleSheet(kTabStyleSheet);

    auto* mainLayout = new QVBoxLayout(this);
    mainLayout->setContentsMargins(6, 6, 6, 6);
    mainLayout->setSpacing(6);

    m_tabWidget = new QTabWidget(this);

    // Create 4 Tabs
    auto* tabMarker  = new QWidget();
    auto* tabTrace   = new QWidget();
    auto* tabDisplay = new QWidget();
    auto* tabExport  = new QWidget();

    setupMarkerTab(tabMarker);
    setupTraceTab(tabTrace);
    setupDisplayTab(tabDisplay);
    setupExportTab(tabExport);

    m_tabWidget->addTab(tabMarker, "Marker");
    m_tabWidget->addTab(tabTrace, "Trace");
    m_tabWidget->addTab(tabDisplay, "View");
    m_tabWidget->addTab(tabExport, "Export");

    mainLayout->addWidget(m_tabWidget);
}

void ControlPanel::setupMarkerTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 8, 8, 8);
    layout->setSpacing(6);

    // Marker Selection Combo
    auto* rowSelect = new QHBoxLayout();
    rowSelect->addWidget(new QLabel("Select:", tab));
    m_markerSelectCombo = new QComboBox(tab);
    m_markerSelectCombo->addItems({"M1 (Cyan)", "M2 (Amber)", "M3 (Pink)", "M4 (SkyBlue)", "M5 (Lime)", "M6 (Coral)"});
    rowSelect->addWidget(m_markerSelectCombo, 1);
    layout->addLayout(rowSelect);

    // Search Grid
    m_btnPeakSearch = new QPushButton("Peak Search", tab);
    m_btnNextPeak   = new QPushButton("Next Peak", tab);

    auto* grid = new QGridLayout();
    grid->setSpacing(4);
    m_btnPeakLeft  = new QPushButton("◀ Peak Left", tab);
    m_btnPeakRight = new QPushButton("Peak Right ▶", tab);
    m_btnMinSearch = new QPushButton("Min Search", tab);

    grid->addWidget(m_btnPeakSearch, 0, 0, 1, 2);
    grid->addWidget(m_btnNextPeak, 1, 0, 1, 2);
    grid->addWidget(m_btnPeakLeft, 2, 0);
    grid->addWidget(m_btnPeakRight, 2, 1);
    grid->addWidget(m_btnMinSearch, 3, 0, 1, 2);
    layout->addLayout(grid);

    // Toggles
    m_btnContinuousPeak = new QPushButton("Continuous Peak: OFF", tab);
    m_btnDeltaToggle    = new QPushButton("Delta Mode (Δ): OFF", tab);
    m_btnClearMarkers   = new QPushButton("Clear All Markers", tab);
    m_btnClearMarkers->setStyleSheet("color: #f87171; border-color: #7f1d1d;");

    layout->addWidget(m_btnContinuousPeak);
    layout->addWidget(m_btnDeltaToggle);
    layout->addWidget(m_btnClearMarkers);

    layout->addStretch(1);

    // Signal connections
    connect(m_markerSelectCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [this](int idx) {
        emit markerSelected(idx + 1);
    });

    connect(m_btnPeakSearch, &QPushButton::clicked, [this]() {
        emit peakSearchRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnNextPeak, &QPushButton::clicked, [this]() {
        emit nextPeakRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnPeakLeft, &QPushButton::clicked, [this]() {
        emit peakLeftRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnPeakRight, &QPushButton::clicked, [this]() {
        emit peakRightRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnMinSearch, &QPushButton::clicked, [this]() {
        emit minSearchRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnContinuousPeak, &QPushButton::clicked, [this]() {
        m_isContinuousPeakActive = !m_isContinuousPeakActive;
        if (m_isContinuousPeakActive) {
            m_btnContinuousPeak->setText("Continuous Peak: ON");
            m_btnContinuousPeak->setStyleSheet("background-color: #064e3b; color: #10b981; border-color: #059669;");
        } else {
            m_btnContinuousPeak->setText("Continuous Peak: OFF");
            m_btnContinuousPeak->setStyleSheet("");
        }
        emit continuousPeakToggled(m_isContinuousPeakActive, m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnDeltaToggle, &QPushButton::clicked, [this]() {
        m_isDeltaActive = !m_isDeltaActive;
        if (m_isDeltaActive) {
            m_btnDeltaToggle->setText("Delta Mode (Δ): ON");
            m_btnDeltaToggle->setStyleSheet("background-color: #0369a1; color: #38bdf8; border-color: #0284c7;");
        } else {
            m_btnDeltaToggle->setText("Delta Mode (Δ): OFF");
            m_btnDeltaToggle->setStyleSheet("");
        }
        emit globalDeltaToggled(m_isDeltaActive, 1);
    });

    connect(m_btnClearMarkers, &QPushButton::clicked, [this]() {
        m_isDeltaActive = false;
        m_isContinuousPeakActive = false;
        m_btnDeltaToggle->setText("Delta Mode (Δ): OFF");
        m_btnDeltaToggle->setStyleSheet("");
        m_btnContinuousPeak->setText("Continuous Peak: OFF");
        m_btnContinuousPeak->setStyleSheet("");
        emit clearAllMarkersRequested();
    });
}

void ControlPanel::setupTraceTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 8, 8, 8);
    layout->setSpacing(8);

    m_chkTrace1 = new QCheckBox("Trace 1: Live (Clear/Write)", tab);
    m_chkTrace1->setChecked(true);
    m_chkTrace1->setStyleSheet("color: #00e5ff;");

    m_chkTrace2 = new QCheckBox("Trace 2: Max Hold", tab);
    m_chkTrace2->setChecked(false);
    m_chkTrace2->setStyleSheet("color: #ffb300;");

    m_chkTrace3 = new QCheckBox("Trace 3: Min Hold", tab);
    m_chkTrace3->setChecked(false);
    m_chkTrace3->setStyleSheet("color: #c084fc;");

    m_chkTrace4 = new QCheckBox("Trace 4: Average (16x)", tab);
    m_chkTrace4->setChecked(false);
    m_chkTrace4->setStyleSheet("color: #38bdf8;");

    m_btnResetTraces = new QPushButton("Reset All Traces", tab);

    layout->addWidget(m_chkTrace1);
    layout->addWidget(m_chkTrace2);
    layout->addWidget(m_chkTrace3);
    layout->addWidget(m_chkTrace4);
    layout->addSpacing(8);
    layout->addWidget(m_btnResetTraces);

    layout->addStretch(1);

    connect(m_chkTrace1, &QCheckBox::toggled, [this](bool checked) {
        emit traceToggled(1, checked);
    });
    connect(m_chkTrace2, &QCheckBox::toggled, [this](bool checked) {
        emit traceToggled(2, checked);
    });
    connect(m_chkTrace3, &QCheckBox::toggled, [this](bool checked) {
        emit traceToggled(3, checked);
    });
    connect(m_chkTrace4, &QCheckBox::toggled, [this](bool checked) {
        emit traceToggled(4, checked);
    });
    connect(m_btnResetTraces, &QPushButton::clicked, this, &ControlPanel::resetAllTracesRequested);
}

void ControlPanel::setupDisplayTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 8, 8, 8);
    layout->setSpacing(8);

    m_btnSpectrogramToggle = new QPushButton("Spectrogram: OFF", tab);
    m_btnFullSpan          = new QPushButton("Full Span (10M~6GHz)", tab);
    m_btnFullSpan->setStyleSheet("background-color: #1e3a5f; color: #38bdf8; border-color: #0284c7;");

    layout->addWidget(m_btnSpectrogramToggle);
    layout->addWidget(m_btnFullSpan);

    layout->addStretch(1);

    connect(m_btnSpectrogramToggle, &QPushButton::clicked, [this]() {
        m_isSpectrogramActive = !m_isSpectrogramActive;
        if (m_isSpectrogramActive) {
            m_btnSpectrogramToggle->setText("Spectrogram: ON");
            m_btnSpectrogramToggle->setStyleSheet("background-color: #064e3b; color: #10b981; border-color: #059669;");
        } else {
            m_btnSpectrogramToggle->setText("Spectrogram: OFF");
            m_btnSpectrogramToggle->setStyleSheet("");
        }
        emit spectrogramToggled(m_isSpectrogramActive);
    });

    connect(m_btnFullSpan, &QPushButton::clicked, this, &ControlPanel::fullSpanRequested);
}

void ControlPanel::setupExportTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 8, 8, 8);
    layout->setSpacing(8);

    m_btnExportCsv       = new QPushButton("Export CSV Trace", tab);
    m_btnExportCsv->setObjectName("BtnExport");
    m_btnSaveScreenshot = new QPushButton("Save Screenshot", tab);
    m_btnSaveScreenshot->setObjectName("BtnExport");

    layout->addWidget(m_btnExportCsv);
    layout->addWidget(m_btnSaveScreenshot);

    layout->addStretch(1);

    connect(m_btnExportCsv, &QPushButton::clicked, this, &ControlPanel::exportCsvRequested);
    connect(m_btnSaveScreenshot, &QPushButton::clicked, this, &ControlPanel::saveScreenshotRequested);
}

void ControlPanel::setStatus(const QString& /*status*/) {}
void ControlPanel::setFps(double /*fps*/) {}
void ControlPanel::setRbw(double /*hz*/) {}
void ControlPanel::setCenterFreq(double /*hz*/) {}
void ControlPanel::setSpan(double /*hz*/) {}
void ControlPanel::setRefLevel(double /*dBm*/) {}

} // namespace rtsa

