ControlPanel::ControlPanel(QWidget* parent)
    : QWidget(parent)
{
    setObjectName("ControlPanel");
    setAutoFillBackground(true);

    QPalette pal = palette();
    pal.setColor(QPalette::Window, QColor(0x1a, 0x1a, 0x2e));
    setPalette(pal);

    setStyleSheet(kControlStyleSheet);
    auto* mainLayout = new QVBoxLayout(this);
    mainLayout->setContentsMargins(10, 8, 10, 10);
    mainLayout->setSpacing(8);

    // ── Status Header ──
    auto* statusWidget = new QWidget(this);
    auto* statusLayout = new QHBoxLayout(statusWidget);
    statusLayout->setContentsMargins(0, 0, 0, 0);
    statusLayout->setSpacing(8);

    m_statusLabel = new QLabel("RUNNING", statusWidget);
    m_statusLabel->setObjectName("StatusHeader");

    m_fpsLabel = new QLabel("0.0 FPS", statusWidget);
    m_fpsLabel->setObjectName("StatusHeader");
    m_fpsLabel->setAlignment(Qt::AlignRight | Qt::AlignVCenter);

    statusLayout->addWidget(m_statusLabel, 1);
    statusLayout->addWidget(m_fpsLabel, 1);
    mainLayout->addWidget(statusWidget);

    // ── Frequency & Span Group ──
    auto* freqGroup = new QGroupBox("INSTRUMENT PARAMETERS", this);
    auto* freqLayout = new QVBoxLayout(freqGroup);
    freqLayout->setSpacing(6);

    auto* cfLabel = new QLabel("Center Frequency (MHz):", freqGroup);
    m_centerFreqSpin = new QDoubleSpinBox(freqGroup);
    m_centerFreqSpin->setRange(10.0, 6000.0); // 10MHz to 6.0GHz (Broadband RFSoC)
    m_centerFreqSpin->setValue(2400.0);
    m_centerFreqSpin->setSingleStep(10.0);
    m_centerFreqSpin->setDecimals(2);
    m_centerFreqSpin->setKeyboardTracking(false);

    auto* spanLabel = new QLabel("Span (MHz):", freqGroup);
    m_spanSpin = new QDoubleSpinBox(freqGroup);
    m_spanSpin->setRange(1.0, 6000.0); // Up to 6GHz full span
    m_spanSpin->setValue(100.0);
    m_spanSpin->setSingleStep(10.0);
    m_spanSpin->setDecimals(2);
    m_spanSpin->setKeyboardTracking(false);

    m_rbwLabel = new QLabel("RBW: 24.41 kHz", freqGroup);
    m_rbwLabel->setStyleSheet("color: #00e5ff; font-weight: bold; padding: 2px;");

    m_btnFullSpan = new QPushButton("Full Span (10M - 6GHz)", freqGroup);
    m_btnFullSpan->setObjectName("BtnFullSpan");

    auto* refLabel = new QLabel("Ref Level (dBm):", freqGroup);
    m_refLevelSpin = new QDoubleSpinBox(freqGroup);
    m_refLevelSpin->setRange(-120.0, 30.0);
    m_refLevelSpin->setValue(0.0);
    m_refLevelSpin->setSingleStep(5.0);
    m_refLevelSpin->setDecimals(1);
    m_refLevelSpin->setKeyboardTracking(false);

    freqLayout->addWidget(cfLabel);
    freqLayout->addWidget(m_centerFreqSpin);
    freqLayout->addWidget(spanLabel);
    freqLayout->addWidget(m_spanSpin);
    freqLayout->addWidget(m_rbwLabel);
    freqLayout->addWidget(m_btnFullSpan);
    freqLayout->addWidget(refLabel);
    freqLayout->addWidget(m_refLevelSpin);

    mainLayout->addWidget(freqGroup);

    // ── Trace Mode Group ──
    auto* traceGroup = new QGroupBox("TRACE & DISPLAY", this);
    auto* traceLayout = new QVBoxLayout(traceGroup);
    traceLayout->setSpacing(6);

    m_traceModeCombo = new QComboBox(traceGroup);
    m_traceModeCombo->addItem("Clear / Write (Live)");
    m_traceModeCombo->addItem("Max Hold");
    m_traceModeCombo->addItem("Min Hold");
    m_traceModeCombo->addItem("Average (10x)");

    m_btnResetTrace = new QPushButton("Reset Trace", traceGroup);

    m_btnSpectrogramToggle = new QPushButton("Spectrogram Off", traceGroup);
    m_btnSpectrogramToggle->setStyleSheet("background-color: #242440; color: #888899;");

    traceLayout->addWidget(m_traceModeCombo);
    traceLayout->addWidget(m_btnResetTrace);
    traceLayout->addWidget(m_btnSpectrogramToggle);
    mainLayout->addWidget(traceGroup);

    // ── Trace Data Export Group ──
    auto* exportGroup = new QGroupBox("TRACE DATA EXPORT", this);
    auto* exportLayout = new QVBoxLayout(exportGroup);
    exportLayout->setSpacing(6);

    m_btnExportCsv = new QPushButton("Export CSV", exportGroup);
    m_btnExportCsv->setObjectName("BtnExport");

    m_btnSaveScreenshot = new QPushButton("Screenshot", exportGroup);
    m_btnSaveScreenshot->setObjectName("BtnExport");

    exportLayout->addWidget(m_btnExportCsv);
    exportLayout->addWidget(m_btnSaveScreenshot);
    mainLayout->addWidget(exportGroup);

    // ── Marker Controls Group ──
    auto* markerGroup = new QGroupBox("MARKER CONTROLS", this);
    auto* markerLayout = new QVBoxLayout(markerGroup);
    markerLayout->setSpacing(6);

    auto* mRow = new QHBoxLayout();
    m_markerSelectCombo = new QComboBox(markerGroup);
    m_markerSelectCombo->addItems({"M1 (Cyan)", "M2 (Amber)", "M3 (Pink)", "M4 (SkyBlue)", "M5 (Lime)", "M6 (Coral)"});
    mRow->addWidget(new QLabel("Sel:", markerGroup));
    mRow->addWidget(m_markerSelectCombo, 1);
    markerLayout->addLayout(mRow);

    m_btnPeakSearch = new QPushButton("Peak Search", markerGroup);
    m_btnNextPeak   = new QPushButton("Next Peak", markerGroup);

    auto* peakRow = new QHBoxLayout();
    auto* btnPeakLeft  = new QPushButton("◀ Left", markerGroup);
    auto* btnPeakRight = new QPushButton("Right ▶", markerGroup);
    peakRow->addWidget(btnPeakLeft);
    peakRow->addWidget(btnPeakRight);

    m_btnMinSearch  = new QPushButton("Min Search", markerGroup);
    m_btnContinuousPeak = new QPushButton("Cont. Peak: OFF", markerGroup);
    m_btnContinuousPeak->setStyleSheet("background-color: #242440; color: #888899;");

    auto* deltaRow = new QHBoxLayout();
    m_btnDeltaToggle = new QPushButton("Delta", markerGroup);
    m_btnDeltaToggle->setStyleSheet("background-color: #242440; color: #888899;");
    m_btnClearMarkers = new QPushButton("Clear", markerGroup);
    m_btnClearMarkers->setStyleSheet("background-color: #402424; color: #ff8888; border-color: #ff4444;");
    deltaRow->addWidget(m_btnDeltaToggle);
    deltaRow->addWidget(m_btnClearMarkers);

    markerLayout->addWidget(m_btnPeakSearch);
    markerLayout->addWidget(m_btnNextPeak);
    markerLayout->addLayout(peakRow);
    markerLayout->addWidget(m_btnMinSearch);
    markerLayout->addWidget(m_btnContinuousPeak);
    markerLayout->addLayout(deltaRow);

    mainLayout->addWidget(markerGroup);

    mainLayout->addStretch(1);

    // ── Internal Signals Connections ──
    connect(m_centerFreqSpin, QOverload<double>::of(&QDoubleSpinBox::valueChanged), [this](double val) {
        emit centerFreqChanged(val * 1e6);
    });

    connect(m_spanSpin, QOverload<double>::of(&QDoubleSpinBox::valueChanged), [this](double val) {
        emit spanChanged(val * 1e6);
    });

    connect(m_refLevelSpin, QOverload<double>::of(&QDoubleSpinBox::valueChanged), [this](double val) {
        emit refLevelChanged(val);
    });

    connect(m_traceModeCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [this](int idx) {
        emit traceModeChanged(static_cast<TraceMode>(idx));
    });

    connect(m_btnFullSpan, &QPushButton::clicked, this, &ControlPanel::fullSpanRequested);
    connect(m_btnExportCsv, &QPushButton::clicked, this, &ControlPanel::exportCsvRequested);
    connect(m_btnSaveScreenshot, &QPushButton::clicked, this, &ControlPanel::saveScreenshotRequested);

    connect(m_btnSpectrogramToggle, &QPushButton::clicked, [this]() {
        m_isSpectrogramActive = !m_isSpectrogramActive;
        if (m_isSpectrogramActive) {
            m_btnSpectrogramToggle->setText("Spectrogram On");
            m_btnSpectrogramToggle->setStyleSheet("background-color: #244030; color: #00ff88; border-color: #00ff88;");
        } else {
            m_btnSpectrogramToggle->setText("Spectrogram Off");
            m_btnSpectrogramToggle->setStyleSheet("background-color: #242440; color: #888899;");
        }
        emit spectrogramToggled(m_isSpectrogramActive);
    });

    connect(m_btnResetTrace, &QPushButton::clicked, this, &ControlPanel::resetTraceRequested);

    connect(m_markerSelectCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [this](int idx) {
        emit markerSelected(idx + 1);
    });

    connect(m_btnPeakSearch, &QPushButton::clicked, [this]() {
        emit peakSearchRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnNextPeak, &QPushButton::clicked, [this]() {
        emit nextPeakRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(btnPeakRight, &QPushButton::clicked, [this]() {
        emit peakRightRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(btnPeakLeft, &QPushButton::clicked, [this]() {
        emit peakLeftRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnMinSearch, &QPushButton::clicked, [this]() {
        emit minSearchRequested(m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnContinuousPeak, &QPushButton::clicked, [this]() {
        m_isContinuousPeakActive = !m_isContinuousPeakActive;
        if (m_isContinuousPeakActive) {
            m_btnContinuousPeak->setText("Cont. Peak: ON");
            m_btnContinuousPeak->setStyleSheet("background-color: #244030; color: #00ff88; border-color: #00ff88;");
        } else {
            m_btnContinuousPeak->setText("Cont. Peak: OFF");
            m_btnContinuousPeak->setStyleSheet("background-color: #242440; color: #888899;");
        }
        emit continuousPeakToggled(m_isContinuousPeakActive, m_markerSelectCombo->currentIndex() + 1);
    });

    connect(m_btnDeltaToggle, &QPushButton::clicked, [this]() {
        m_isDeltaActive = !m_isDeltaActive;
        if (m_isDeltaActive) {
            m_btnDeltaToggle->setText("Delta: ON");
            m_btnDeltaToggle->setStyleSheet("background-color: #1b3854; color: #00e5ff; border-color: #00e5ff;");
        } else {
            m_btnDeltaToggle->setText("Delta: OFF");
            m_btnDeltaToggle->setStyleSheet("background-color: #242440; color: #888899;");
        }
        emit globalDeltaToggled(m_isDeltaActive, 1);
    });

    connect(m_btnClearMarkers, &QPushButton::clicked, [this]() {
        m_isDeltaActive = false;
        m_isContinuousPeakActive = false;
        m_btnDeltaToggle->setText("Delta: OFF");
        m_btnDeltaToggle->setStyleSheet("background-color: #242440; color: #888899;");
        m_btnContinuousPeak->setText("Cont. Peak: OFF");
        m_btnContinuousPeak->setStyleSheet("background-color: #242440; color: #888899;");
        emit clearAllMarkersRequested();
    });
}

void ControlPanel::setCenterFreq(double hz)
{
    m_centerFreqSpin->blockSignals(true);
    m_centerFreqSpin->setValue(hz / 1e6);
    m_centerFreqSpin->blockSignals(false);
}

void ControlPanel::setSpan(double hz)
{
    m_spanSpin->blockSignals(true);
    m_spanSpin->setValue(hz / 1e6);
    m_spanSpin->blockSignals(false);
}

void ControlPanel::setRefLevel(double dBm)
{
    m_refLevelSpin->blockSignals(true);
    m_refLevelSpin->setValue(dBm);
    m_refLevelSpin->blockSignals(false);
}

void ControlPanel::setTraceMode(TraceMode mode)
{
    m_traceModeCombo->blockSignals(true);
    m_traceModeCombo->setCurrentIndex(static_cast<int>(mode));
    m_traceModeCombo->blockSignals(false);
}

void ControlPanel::setStatus(const QString& status)
{
    m_statusLabel->setText(status);
}

void ControlPanel::setFps(double fps)
{
    m_fpsLabel->setText(QString("%1 FPS").arg(fps, 0, 'f', 1));
}

void ControlPanel::setRbw(double hz)
{
    if (hz >= 1e6) {
        m_rbwLabel->setText(QString("RBW: %1 MHz").arg(hz / 1e6, 0, 'f', 2));
    } else if (hz >= 1e3) {
        m_rbwLabel->setText(QString("RBW: %1 kHz").arg(hz / 1e3, 0, 'f', 2));
    } else {
        m_rbwLabel->setText(QString("RBW: %1 Hz").arg(hz, 0, 'f', 1));
    }
}

QString ControlPanel::formatFrequency(double hz) const
{
    if (hz >= 1e9) return QString("%1 GHz").arg(hz / 1e9, 0, 'f', 3);
    if (hz >= 1e6) return QString("%1 MHz").arg(hz / 1e6, 0, 'f', 2);
    if (hz >= 1e3) return QString("%1 kHz").arg(hz / 1e3, 0, 'f', 1);
    return QString("%1 Hz").arg(hz, 0, 'f', 0);
}

} // namespace rtsa

