        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        border: 1px solid #334155;
        border-radius: 3px;
        padding: 4px 6px;
        min-height: 22px;
    }
    QComboBox::drop-down {
        border: none;
        width: 18px;
    }
    QComboBox QAbstractItemView {
        background-color: #1a2030;
        color: #00e5ff;
        selection-background-color: #2e3850;
        selection-color: #ffffff;
    }
    QCheckBox {
        color: #e2e8f0;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        spacing: 6px;
    }
    QCheckBox::indicator {
        width: 14px;
        height: 14px;
        border: 1px solid #475569;
        border-radius: 2px;
        background-color: #1a2030;
