        border-radius: 3px;
        padding: 5px 8px;
        min-height: 22px;
    }
    QPushButton:hover {
        background-color: #283248;
        border-color: #00e5ff;
        color: #ffffff;
    }
    QPushButton:pressed {
        background-color: #00e5ff;
        color: #0a0c14;
    }
    QPushButton#BtnExport {
        background-color: #064e3b;
        color: #10b981;
