    spectrumPlot->setSpan(100e6);
    spectrumPlot->setRefLevel(0.0);
    spectrumPlot->setDbPerDiv(10.0);

    auto* spectrogramWidget = new rtsa::SpectrogramWidget();
    spectrogramWidget->setParams(2.4e9, 100e6, 0.0);
    spectrogramWidget->hide(); // Hidden until user clicks Spectrogram ON

    leftLayout->addWidget(spectrumPlot, 3);
    leftLayout->addWidget(spectrogramWidget, 2);

    // Right-side sidebar layout (Single Unified ControlPanel)
    auto* rightSidebar = new QWidget();
    rightSidebar->setFixedWidth(290);
    rightSidebar->setAutoFillBackground(true);
    QPalette sidePal = rightSidebar->palette();
    sidePal.setColor(QPalette::Window, QColor(0x1a, 0x1a, 0x2e));
    rightSidebar->setPalette(sidePal);

    auto* sidebarLayout = new QVBoxLayout(rightSidebar);
    sidebarLayout->setContentsMargins(0, 0, 0, 0);
    sidebarLayout->setSpacing(0);

    auto* controlPanel = new rtsa::ControlPanel();

    controlPanel->setCenterFreq(2.4e9);
    controlPanel->setSpan(100e6);
    controlPanel->setRefLevel(0.0);
    controlPanel->setRbw(100e6 / 4096);
    controlPanel->setStatus(fsmController->stateString());

    sidebarLayout->addWidget(controlPanel, 1);

    mainLayout->addWidget(leftContainer, 1);
    mainLayout->addWidget(rightSidebar, 0);
    window.setCentralWidget(centralWidget);

    // ── Create Data Processor (T2) ──
    auto* dataProcessor = new rtsa::DataProcessor(tripleBuffer, 4096);
    dataProcessor->setParams(2.4e9, 100e6);

    // Connect SpectrumPlot to MarkerEngine
    spectrumPlot->setMarkerEngine(&dataProcessor->markerEngine());

    // Connect T2 -> T3 (SpectrumPlot & SpectrogramWidget)
    QObject::connect(dataProcessor, &rtsa::DataProcessor::frameReady,
                     spectrumPlot, &rtsa::SpectrumPlot::onNewFrame,
                     Qt::QueuedConnection);

    QObject::connect(dataProcessor, &rtsa::DataProcessor::frameReady,
                     spectrogramWidget, &rtsa::SpectrogramWidget::onNewFrame,
                     Qt::QueuedConnection);

    // Connect Marker Updates -> SpectrumPlot Repaint
    QObject::connect(dataProcessor, &rtsa::DataProcessor::markersUpdated,
                     spectrumPlot, QOverload<>::of(&QWidget::update),
                     Qt::QueuedConnection);

    // ── Connect ControlPanel Interactions ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::centerFreqChanged, [=](double hz) {
        paramTxn->setCenterFreq(hz);
        if (paramTxn->commit()) {
            spectrumPlot->setCenterFreq(hz);
            spectrogramWidget->setParams(hz, spectrumPlot->span(), spectrumPlot->refLevel());
            dataProcessor->setParams(hz, spectrumPlot->span());
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::spanChanged, [=](double hz) {
        paramTxn->setSpan(hz);
        if (paramTxn->commit()) {
            spectrumPlot->setSpan(hz);
            spectrogramWidget->setParams(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
            controlPanel->setRbw(hz / 4096);
            dataProcessor->setParams(spectrumPlot->centerFreq(), hz);
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::refLevelChanged, [=](double dBm) {
        paramTxn->setRefLevel(dBm);
        if (paramTxn->commit()) {
            spectrumPlot->setRefLevel(dBm);
            spectrogramWidget->setParams(spectrumPlot->centerFreq(), spectrumPlot->span(), dBm);
        }
    });

    // ── Connect SpectrumPlot Mouse Drag & Wheel Shortcuts -> ControlPanel & Hardware ──
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::centerFreqUserChanged, [=](double hz) {
        paramTxn->setCenterFreq(hz);
        if (paramTxn->commit()) {
            controlPanel->setCenterFreq(hz);
            spectrogramWidget->setParams(hz, spectrumPlot->span(), spectrumPlot->refLevel());
            dataProcessor->setParams(hz, spectrumPlot->span());
        }
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::spanUserChanged, [=](double hz) {
        paramTxn->setSpan(hz);
        if (paramTxn->commit()) {
            controlPanel->setSpan(hz);
            spectrogramWidget->setParams(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
            controlPanel->setRbw(hz / 4096);
            dataProcessor->setParams(spectrumPlot->centerFreq(), hz);
        }
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::refLevelUserChanged, [=](double dBm) {
        paramTxn->setRefLevel(dBm);
        if (paramTxn->commit()) {
            controlPanel->setRefLevel(dBm);
            spectrogramWidget->setParams(spectrumPlot->centerFreq(), spectrumPlot->span(), dBm);
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::spectrogramToggled, [spectrogramWidget](bool show) {
        if (show) {
            spectrogramWidget->show();
        } else {
            spectrogramWidget->hide();
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::traceModeChanged, [=](rtsa::TraceMode mode) {
        dataProcessor->setTraceMode(mode);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::continuousPeakToggled, [=](bool enabled, int markerId) {
        dataProcessor->setContinuousPeak(enabled, markerId);
    });

    // ── Full Span Shortcut ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::fullSpanRequested, [=]() {
        double fullCenter = 3005.0e6; // 3.005 GHz
        double fullSpan   = 5990.0e6; // 5.990 GHz (10MHz ~ 6000MHz)

        paramTxn->setCenterFreq(fullCenter);
        paramTxn->setSpan(fullSpan);
        if (paramTxn->commit()) {
            spectrumPlot->setCenterFreq(fullCenter);
            spectrumPlot->setSpan(fullSpan);
            spectrogramWidget->setParams(fullCenter, fullSpan, spectrumPlot->refLevel());
            controlPanel->setCenterFreq(fullCenter);
            controlPanel->setSpan(fullSpan);
            controlPanel->setRbw(fullSpan / 4096);
            dataProcessor->setParams(fullCenter, fullSpan);
            rtsa::Logger::info("Main", "Full Span set: 10 MHz to 6.0 GHz");
        }
    });

    // ── Screenshot Archiving ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::saveScreenshotRequested, [&window]() {
        QDir exportDir("exports");
        if (!exportDir.exists()) {
            QDir().mkdir("exports");
        }
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString filename = QString("exports/screenshot_%1.png").arg(timestamp);

        QPixmap pixmap = window.grab();
        if (pixmap.save(filename)) {
            rtsa::Logger::info("Main", QString("Screenshot saved to %1").arg(filename));
            QMessageBox::information(&window, "Screenshot Saved",
                                     QString("Screenshot successfully saved to:\n%1").arg(filename));
        } else {
            rtsa::Logger::error("Main", "Failed to save screenshot");
            QMessageBox::warning(&window, "Error", "Failed to save screenshot image.");
        }
    });

    // ── CSV Data Export ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::exportCsvRequested, [dataProcessor, spectrumPlot, &window]() {
        QDir exportDir("exports");
        if (!exportDir.exists()) {
            QDir().mkdir("exports");
        }
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString filename = QString("exports/trace_%1.csv").arg(timestamp);

        QFile file(filename);
        if (file.open(QIODevice::WriteOnly | QIODevice::Text)) {
            QTextStream out(&file);
            out << "Frequency_Hz,Amplitude_dBm\n";

            double centerFreq = spectrumPlot->centerFreq();
            double span = spectrumPlot->span();
            double startFreq = centerFreq - span / 2.0;

            std::vector<float> processeddBm = dataProcessor->currentSpectrumTrace();
            int count = static_cast<int>(processeddBm.size());

            if (count > 0) {
                for (int i = 0; i < count; ++i) {
                    double freq = startFreq + (static_cast<double>(i) / count) * span;
                    out << QString::number(freq, 'f', 2) << ","
                        << QString::number(processeddBm[i], 'f', 2) << "\n";
                }
            }

            file.close();
            rtsa::Logger::info("Main", QString("Trace CSV exported to %1 (%2 points)")
                                           .arg(filename)
                                           .arg(count));
            QMessageBox::information(&window, "CSV Exported",
                                     QString("Trace data successfully exported to:\n%1\n(%2 points)").arg(filename).arg(count));
        } else {
            rtsa::Logger::error("Main", "Failed to create CSV export file");
            QMessageBox::warning(&window, "Error", "Failed to create CSV export file.");
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::resetTraceRequested, [=]() {
        dataProcessor->resetTrace();
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::markerSelected, [=](int id) {
        // If selected marker is not active yet, run initial peak search to place it
        if (!dataProcessor->markerEngine().marker(id).active) {
            dataProcessor->triggerPeakSearch(id);
        }
        // If already active, DO NOT move it! Retain its existing position!
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakSearchRequested, [=](int id) {
        dataProcessor->triggerPeakSearch(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::nextPeakRequested, [=](int id) {
        dataProcessor->triggerNextPeak(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakRightRequested, [=](int id) {
        dataProcessor->triggerNextPeakRight(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakLeftRequested, [=](int id) {
        dataProcessor->triggerNextPeakLeft(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::minSearchRequested, [=](int id) {
        dataProcessor->triggerMinSearch(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::globalDeltaToggled, [=](bool enable, int refId) {
        dataProcessor->markerEngine().setGlobalDelta(enable, refId);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::clearAllMarkersRequested, [=]() {
        dataProcessor->markerEngine().setGlobalDelta(false, 1);
        for (int i = 1; i <= 6; ++i) {
            dataProcessor->markerEngine().setMarkerActive(i, false);
        }
    });

    // ── FPS Timer ──
    auto* fpsTimer = new QTimer();
    QObject::connect(fpsTimer, &QTimer::timeout, [spectrumPlot, controlPanel]() {
        controlPanel->setFps(spectrumPlot->currentFps());
    });
    fpsTimer->start(500);

    // ── Create T1 DMA Thread ──
    auto* dmaThread = new rtsa::DmaRecvThread(hal, tripleBuffer);

    // Start threads & FSM
    fsmController->startRunning();
    controlPanel->setStatus(fsmController->stateString());

    dataProcessor->start();
    dmaThread->start();

    window.show();
    rtsa::Logger::info("Main", "Application ready with M3 full interactive features");

    int result = app.exec();

    // Shutdown
    dmaThread->stopThread();
    dmaThread->wait(2000);

    dataProcessor->stopThread();
    dataProcessor->wait(2000);

    fpsTimer->stop();

    delete fpsTimer;
    delete dmaThread;
    delete dataProcessor;
    delete tripleBuffer;
    delete paramTxn;
    delete fsmController;
    delete mock;

    return result;
}

