67:     const int windowRadius = std::max(10, size / 150);
68:     const float noiseFloorThreshold = -85.0f;
69: 
70:     for (int i = windowRadius; i < size - windowRadius; ++i) {
71:         if (dBmArray[i] < noiseFloorThreshold) continue;
72: 
73:         bool isLocalMax = true;
74:         for (int j = i - windowRadius; j <= i + windowRadius; ++j) {
75:             if (j != i && dBmArray[j] >= dBmArray[i]) {
76:                 isLocalMax = false;
