238:     // Next compute global Delta for all active markers relative to globalRefMarkerId
239:     if (m_globalDeltaEnabled && m_globalRefMarkerId >= 1 && m_globalRefMarkerId <= kMaxMarkers) {
240:         const auto& refM = m_markers[m_globalRefMarkerId - 1];
