#ifndef RTSA_MARKER_ENGINE_H
#define RTSA_MARKER_ENGINE_H

#include <vector>
#include <array>
#include <cstdint>
#include <QColor>

namespace rtsa {

struct MarkerInfo {
    int id = 1;                 // Marker ID 1..6
    bool active = false;        // Enabled or disabled
    int binIndex = 0;           // Bin index in FFT array
    double freqHz = 0.0;        // Frequency at bin
    double amplitude = 0.0;     // Amplitude at bin (dBm)
    bool isDelta = false;       // Is delta marker
    int refMarkerId = 1;        // Reference marker ID
    double deltaFreqHz = 0.0;   // Delta frequency relative to ref
    double deltaAmplitude = 0.0;// Delta amplitude relative to ref
    bool continuousPeak = false;// Independent Continuous Peak Search toggle per marker
    QColor color;               // Distinct color for each marker
};

struct LocalPeak {
    int binIndex = 0;
    float amplitude = 0.0f;
    double freqHz = 0.0;
};

class MarkerEngine {
public:
    static constexpr int kMaxMarkers = 6;

    MarkerEngine();

    MarkerInfo& marker(int id);
    const MarkerInfo& marker(int id) const;

    void setMarkerActive(int id, bool active);
    void setMarkerBin(int id, int binIndex, double centerFreqHz, double spanHz, int fftSize);

    /// Independent Continuous Peak Search per Marker
    void setContinuousPeak(int id, bool enable);
    bool isContinuousPeak(int id) const;

    /// Enable/Disable Global Delta mode against a specified Reference Marker
