void MarkerEngine::setContinuousPeak(int id, bool enable)
{
    marker(id).continuousPeak = enable;
    if (enable) {
        marker(id).active = true;
    }
}

bool MarkerEngine::isContinuousPeak(int id) const
{
    return marker(id).continuousPeak;
}

void MarkerEngine::findLocalPeaks(const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    m_detectedPeaks.clear();
    if (!dBmArray || size < 3) return;

    double startFreq = centerFreqHz - spanHz / 2.0;
    const int windowRadius = std::max(5, size / 200);

    // Fast candidate filter: local inflection point (derivative zero crossing)
    for (int i = 1; i < size - 1; ++i) {
        if (dBmArray[i] <= dBmArray[i - 1] || dBmArray[i] < dBmArray[i + 1]) {
            continue; // Not a local peak candidate
        }

        // Window check around candidate
        int leftBound  = std::max(0, i - windowRadius);
        int rightBound = std::min(size - 1, i + windowRadius);
        bool isMaxInWindow = true;

        for (int j = leftBound; j <= rightBound; ++j) {
            if (j != i && dBmArray[j] > dBmArray[i]) {
                isMaxInWindow = false;
                break;
            }
        }

        if (isMaxInWindow) {
            LocalPeak peak;
            peak.binIndex = i;
            peak.amplitude = dBmArray[i];
            peak.freqHz = startFreq + (static_cast<double>(i) / size) * spanHz;
            m_detectedPeaks.push_back(peak);
        }
    }

    // Sort up to top 30 detected peaks to avoid excessive sort overhead
    if (m_detectedPeaks.size() > 30) {
        std::partial_sort(m_detectedPeaks.begin(), m_detectedPeaks.begin() + 30, m_detectedPeaks.end(),
                          [](const LocalPeak& a, const LocalPeak& b) { return a.amplitude > b.amplitude; });
        m_detectedPeaks.resize(30);
    } else {
        std::sort(m_detectedPeaks.begin(), m_detectedPeaks.end(), [](const LocalPeak& a, const LocalPeak& b) {
            return a.amplitude > b.amplitude;
        });
    }
}

// Ultra-fast O(N) single-pass peak search (No findLocalPeaks overhead!)
void MarkerEngine::searchPeak(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (!dBmArray || size <= 0) return;

    int maxBin = 0;
    float maxVal = dBmArray[0];

    for (int i = 1; i < size; ++i) {
        if (dBmArray[i] > maxVal) {
            maxVal = dBmArray[i];
            maxBin = i;
        }
    }

    auto& m = marker(id);
    m.active = true;
    m.binIndex = maxBin;
    m.amplitude = maxVal;
    double startFreq = centerFreqHz - spanHz / 2.0;
    m.freqHz = startFreq + (static_cast<double>(maxBin) / size) * spanHz;
}

