#include <QGraphicsDropShadowEffect>
#include <algorithm>

namespace rtsa {

static const QString kCardStyleSheet = R"(
    QWidget#MarkerCard {
        background-color: rgba(18, 18, 36, 240);
        border: 1px solid #4488ff;
        border-radius: 6px;
    }
    QLabel#CardHeader {
        color: #00e5ff;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        padding: 5px 8px;
        background-color: rgba(30, 30, 54, 220);
        border-top-left-radius: 5px;
        border-top-right-radius: 5px;
    }
    QLabel#TableHeader {
        color: #4488ff;
        font-family: Consolas, monospace;
        font-size: 11px;
        font-weight: bold;
        padding-bottom: 2px;
    }
)";

MarkerCard::MarkerCard(QWidget* parent)
    : QWidget(parent)
{
    setObjectName("MarkerCard");
    setStyleSheet(kCardStyleSheet);
    setCursor(Qt::SizeAllCursor);

    // Shadow effect
    auto* shadow = new QGraphicsDropShadowEffect(this);
    shadow->setBlurRadius(15);
    shadow->setColor(QColor(0, 0, 0, 180));
    shadow->setOffset(0, 4);
    setGraphicsEffect(shadow);

    auto* mainLayout = new QVBoxLayout(this);
    mainLayout->setContentsMargins(0, 0, 0, 6);
    mainLayout->setSpacing(4);

    // Card Header (Title bar)
    auto* headerLabel = new QLabel(":: MARKER DATA (DRAGGABLE)", this);
    headerLabel->setObjectName("CardHeader");
    mainLayout->addWidget(headerLabel);

    // Table Header
    auto* tableHeader = new QWidget(this);
    auto* thLayout = new QHBoxLayout(tableHeader);
    thLayout->setContentsMargins(10, 4, 10, 2);
    thLayout->setSpacing(8);

    auto* lblMkr  = new QLabel("MKR", tableHeader);
    auto* lblFreq = new QLabel("FREQUENCY", tableHeader);
    auto* lblAmp  = new QLabel("AMPLITUDE", tableHeader);
    auto* lblDelta= new QLabel("DELTA / REF", tableHeader);

    lblMkr->setObjectName("TableHeader");
    lblFreq->setObjectName("TableHeader");
    lblAmp->setObjectName("TableHeader");
    lblDelta->setObjectName("TableHeader");

    lblMkr->setFixedWidth(44);
    lblFreq->setFixedWidth(105);
    lblAmp->setFixedWidth(85);

    thLayout->addWidget(lblMkr);
    thLayout->addWidget(lblFreq);
    thLayout->addWidget(lblAmp);
    thLayout->addWidget(lblDelta, 1);

    mainLayout->addWidget(tableHeader);

    // Container for 6 pre-created rows
    auto* contentWidget = new QWidget(this);
    auto* contentLayout = new QVBoxLayout(contentWidget);
    contentLayout->setContentsMargins(10, 0, 10, 0);
    contentLayout->setSpacing(3);

    for (int i = 0; i < 6; ++i) {
        auto& row = m_rows[i];
        row.container = new QWidget(contentWidget);
        auto* rowLayout = new QHBoxLayout(row.container);
        rowLayout->setContentsMargins(0, 2, 0, 2);
        rowLayout->setSpacing(8);

        row.lblId   = new QLabel(QString("M%1").arg(i + 1), row.container);
        row.lblFreq = new QLabel("--", row.container);
        row.lblAmp  = new QLabel("-- dBm", row.container);
        row.lblDelta= new QLabel("--", row.container);

        row.lblId->setFixedWidth(44);
        row.lblFreq->setFixedWidth(105);
        row.lblAmp->setFixedWidth(85);

        rowLayout->addWidget(row.lblId);
        rowLayout->addWidget(row.lblFreq);
        rowLayout->addWidget(row.lblAmp);
        rowLayout->addWidget(row.lblDelta, 1);

        contentLayout->addWidget(row.container);
        row.container->hide();
    }

    mainLayout->addWidget(contentWidget);

    setMinimumWidth(430);
    adjustSize();
    hide();
}

void MarkerCard::updateMarkers(const MarkerEngine* engine)
{
    if (!engine) {
        hide();
        return;
    }

    int activeCount = 0;

    for (int i = 0; i < 6; ++i) {
        const auto& m = engine->marker(i + 1);
        auto& row = m_rows[i];

        if (m.active) {
            activeCount++;
            row.container->show();

            row.lblId->setText(QString("M%1").arg(m.id));
            row.lblFreq->setText(formatFrequency(m.freqHz));
            row.lblAmp->setText(QString("%1 dBm").arg(m.amplitude, 0, 'f', 1));

            QString colorHex = m.color.name();
            QString cellStyle = QString("color: %1; font-family: Consolas; font-size: 12px; font-weight: bold;").arg(colorHex);

            row.lblId->setStyleSheet(cellStyle);
            row.lblFreq->setStyleSheet(cellStyle);
            row.lblAmp->setStyleSheet(cellStyle);
            row.lblDelta->setStyleSheet(cellStyle);

            if (m.isDelta) {
                int refId = (m.refMarkerId >= 1) ? m.refMarkerId : 1;
                row.lblDelta->setText(QString("Δ(M%1-M%2): %3, %4 dB")
                                          .arg(m.id)
                                          .arg(refId)
                                          .arg(formatFrequency(m.deltaFreqHz))
                                          .arg(m.deltaAmplitude, 0, 'f', 1));
            } else {
                row.lblDelta->setText("--");
            }
        } else {
            row.container->hide();
        }
    }

    adjustSize();

    if (activeCount > 0) {
        if (isHidden()) {
            show();
            if (parentWidget()) {
                move(parentWidget()->width() - width() - 25, 45);
            }
        }
    } else {
        hide();
    }
}

// ── Mouse Dragging ──

void MarkerCard::mousePressEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        m_isDragging = true;
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
        m_dragPosition = event->globalPosition().toPoint() - frameGeometry().topLeft();
#else
        m_dragPosition = event->globalPos() - frameGeometry().topLeft();
#endif
        event->accept();
    }
}

void MarkerCard::mouseMoveEvent(QMouseEvent* event)
{
    if (m_isDragging && (event->buttons() & Qt::LeftButton)) {
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
        QPoint newPos = event->globalPosition().toPoint() - m_dragPosition;
#else
        QPoint newPos = event->globalPos() - m_dragPosition;
#endif

        if (parentWidget()) {
            int maxX = parentWidget()->width() - width();
            int maxY = parentWidget()->height() - height();
            newPos.setX(std::clamp(newPos.x(), 0, std::max(0, maxX)));
            newPos.setY(std::clamp(newPos.y(), 0, std::max(0, maxY)));
        }

        move(newPos);
        event->accept();
    }
}

void MarkerCard::mouseReleaseEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        m_isDragging = false;
        event->accept();
    }
}

QString MarkerCard::formatFrequency(double hz) const
{
    double absHz = std::abs(hz);
    QString prefix = (hz < 0) ? "-" : "";

    if (absHz >= 1e9)
        return QString("%1%2 G").arg(prefix).arg(absHz / 1e9, 0, 'f', 3);
    if (absHz >= 1e6)
        return QString("%1%2 M").arg(prefix).arg(absHz / 1e6, 0, 'f', 2);
    if (absHz >= 1e3)
        return QString("%1%2 k").arg(prefix).arg(absHz / 1e3, 0, 'f', 1);
    return QString("%1%2 Hz").arg(prefix).arg(absHz, 0, 'f', 0);
}

} // namespace rtsa

