#include "TopBarWidget.h"

#include <QHBoxLayout>
#include <QFrame>

namespace rtsa {

TopBarWidget::TopBarWidget(QWidget* parent)
    : QWidget(parent)
{
    setFixedHeight(38);
    setObjectName("TopBarWidget");
    setStyleSheet(R"(
        QWidget#TopBarWidget {
            background-color: #121520;
            border-bottom: 1px solid #283248;
        }
        QLabel {
            color: #94a3b8;
            font-family: "KaiTi", "STKaiti", "楷体", serif;
            font-size: 12px;
        }
        QLabel#Title {
            color: #00e5ff;
            font-size: 13px;
            font-weight: bold;
        }
        QLabel#DeviceTag {
            color: #10b981;
            background-color: #064e3b;
            border: 1px solid #059669;
            border-radius: 3px;
            padding: 2px 6px;
            font-weight: bold;
            font-size: 11px;
        }
        QPushButton {
            font-family: "KaiTi", "STKaiti", "楷体", serif;
            font-size: 12px;
            font-weight: bold;
            border-radius: 3px;
            padding: 3px 10px;
            min-height: 22px;
        }
    )");

    auto* layout = new QHBoxLayout(this);
    layout->setContentsMargins(10, 4, 10, 4);
    layout->setSpacing(8);

    // ── Acquisition Controls (RUN / SINGLE / STOP) ──
    m_btnRun    = new QPushButton("● 运行", this);
    m_btnSingle = new QPushButton("❚❚ 单次", this);
    m_btnStop   = new QPushButton("■ 停止", this);

    connect(m_btnRun, &QPushButton::clicked, this, &TopBarWidget::runRequested);
    connect(m_btnSingle, &QPushButton::clicked, this, &TopBarWidget::singleRequested);
    connect(m_btnStop, &QPushButton::clicked, this, &TopBarWidget::stopRequested);

    layout->addWidget(m_btnRun);
    layout->addWidget(m_btnSingle);
    layout->addWidget(m_btnStop);

    auto* sep1 = new QFrame(this);
    sep1->setFrameShape(QFrame::VLine);
    sep1->setStyleSheet("color: #283248;");
    layout->addWidget(sep1);

    // ── Application Title & Device Indicator ──
    m_titleLabel = new QLabel("RTSA-X 实时频谱与信号分析仪", this);
    m_titleLabel->setObjectName("Title");
    layout->addWidget(m_titleLabel);

    m_deviceLabel = new QLabel("● 硬件连接正常", this);
    m_deviceLabel->setObjectName("DeviceTag");
    layout->addWidget(m_deviceLabel);

    layout->addStretch(1);

    // ── Live Acquisition & Hardware Status Readouts ──
    m_rtbwLabel = new QLabel("实时带宽: <span style='color:#38bdf8;font-weight:bold;'>100.0 MHz</span>", this);
    m_rbwLabel  = new QLabel("分辨率带宽: <span style='color:#e2e8f0;font-weight:bold;'>24.4 kHz</span>", this);
    m_poiLabel  = new QLabel("截获概率: <span style='color:#10b981;font-weight:bold;'>100%</span>", this);
    m_fftLabel  = new QLabel("FFT速率: <span style='color:#e2e8f0;font-weight:bold;'>15.2 k/s</span>", this);
    m_fpsLabel  = new QLabel("刷新率: <span style='color:#00e5ff;font-weight:bold;'>0.0 FPS</span>", this);

    layout->addWidget(m_rtbwLabel);
    layout->addWidget(m_rbwLabel);
    layout->addWidget(m_poiLabel);
    layout->addWidget(m_fftLabel);
    layout->addWidget(m_fpsLabel);

    updateButtonStyles();
}

void TopBarWidget::setRunState(RunState state)
{
    m_runState = state;
    updateButtonStyles();
}

void TopBarWidget::updateButtonStyles()
{
    if (m_runState == RunState::Running) {
        m_btnRun->setStyleSheet("background-color: #059669; color: #ffffff; border: 1px solid #10b981;");
        m_btnSingle->setStyleSheet("background-color: #1e2538; color: #94a3b8; border: 1px solid #334155;");
        m_btnStop->setStyleSheet("background-color: #1e2538; color: #94a3b8; border: 1px solid #334155;");
    } else if (m_runState == RunState::Single) {
        m_btnRun->setStyleSheet("background-color: #1e2538; color: #94a3b8; border: 1px solid #334155;");
        m_btnSingle->setStyleSheet("background-color: #d97706; color: #ffffff; border: 1px solid #f59e0b;");
        m_btnStop->setStyleSheet("background-color: #1e2538; color: #94a3b8; border: 1px solid #334155;");
    } else { // Stopped
        m_btnRun->setStyleSheet("background-color: #1e2538; color: #94a3b8; border: 1px solid #334155;");
        m_btnSingle->setStyleSheet("background-color: #1e2538; color: #94a3b8; border: 1px solid #334155;");
        m_btnStop->setStyleSheet("background-color: #dc2626; color: #ffffff; border: 1px solid #ef4444;");
    }
}

void TopBarWidget::setRtbw(double hz)
{
    if (hz >= 1e9)
        m_rtbwLabel->setText(QString("实时带宽: <span style='color:#38bdf8;font-weight:bold;'>%1 GHz</span>").arg(hz / 1e9, 0, 'f', 2));
    else
        m_rtbwLabel->setText(QString("实时带宽: <span style='color:#38bdf8;font-weight:bold;'>%1 MHz</span>").arg(hz / 1e6, 0, 'f', 1));
}

void TopBarWidget::setRbw(double hz)
{
    if (hz >= 1e6)
        m_rbwLabel->setText(QString("分辨率带宽: <span style='color:#e2e8f0;font-weight:bold;'>%1 MHz</span>").arg(hz / 1e6, 0, 'f', 2));
    else if (hz >= 1e3)
        m_rbwLabel->setText(QString("分辨率带宽: <span style='color:#e2e8f0;font-weight:bold;'>%1 kHz</span>").arg(hz / 1e3, 0, 'f', 1));
    else
        m_rbwLabel->setText(QString("分辨率带宽: <span style='color:#e2e8f0;font-weight:bold;'>%1 Hz</span>").arg(hz, 0, 'f', 0));
}

void TopBarWidget::setFps(double fps)
{
    m_fpsLabel->setText(QString("刷新率: <span style='color:#00e5ff;font-weight:bold;'>%1 FPS</span>").arg(fps, 0, 'f', 1));
}

void TopBarWidget::setFftRate(const QString& rateStr)
{
    m_fftLabel->setText(QString("FFT速率: <span style='color:#e2e8f0;font-weight:bold;'>%1</span>").arg(rateStr));
}

void TopBarWidget::setPoi(const QString& poiStr)
{
    m_poiLabel->setText(QString("截获概率: <span style='color:#10b981;font-weight:bold;'>%1</span>").arg(poiStr));
}

} // namespace rtsa

