#include <QApplication>
#include <QHBoxLayout>
#include <QVBoxLayout>
#include <QMainWindow>
#include <QString>
#include <QTimer>
#include <QDir>
#include <QDateTime>
#include <QFile>
#include <QTextStream>
#include <QMessageBox>
#include <QFont>

#include "TopBarWidget.h"
#include "BottomParamBar.h"
#include "ControlPanel.h"
#include "DataProcessor.h"
#include "DmaRecvThread.h"
#include "FsmController.h"
#include "Logger.h"
#include "MockDmaManager.h"
#include "ParamTransaction.h"
#include "ProcessedFrame.h"
#include "SpectrumFrame.h"
#include "SpectrumPlot.h"
#include "SpectrogramWidget.h"
#include "TripleBuffer.h"

int main(int argc, char* argv[])
{
    QApplication app(argc, argv);
    app.setApplicationName("RTSA-X 实时信号分析仪");
    app.setApplicationVersion("2.1.0");

    // Set Global Font to KaiTi
    QFont kaiTiFont("KaiTi", 10);
    kaiTiFont.setStyleHint(QFont::Serif);
    app.setFont(kaiTiFont);

    qRegisterMetaType<rtsa::ProcessedFrame>("rtsa::ProcessedFrame");

    rtsa::Logger::init();
    rtsa::Logger::info("Main", "RTSA-X 实时信号分析仪 2.1 正在启动...");

    // ── Select HAL ──
    bool useMock = true;
    for (int i = 1; i < argc; ++i) {
        if (QString(argv[i]) == "--real") {
            useMock = false;
        }
    }

    rtsa::MockDmaManager* mock = nullptr;
    rtsa::IHalInterface* hal   = nullptr;

    if (useMock) {
        mock = new rtsa::MockDmaManager(4096);
        mock->setNoiseFloor(-100.0);
        mock->setFrameIntervalMs(1);
        mock->setSignals({
            {2.412e9, -30.0, 2e6}, // WiFi Channel 1
            {2.437e9, -45.0, 2e6}, // WiFi Channel 6
            {2.462e9, -55.0, 2e6}, // WiFi Channel 11
        });
        hal = mock;
        rtsa::Logger::info("Main", "启动 Mock 模拟数据源 (4096 点 FFT)");
    } else {
        rtsa::Logger::error("Main", "硬件 DMA 驱动尚未就绪");
        return 1;
    }

    // ── Core Controllers ──
    auto tripleBuffer  = new rtsa::TripleBuffer<rtsa::SpectrumFrame>();
    auto fsmController = new rtsa::FsmController();
    auto paramTxn      = new rtsa::ParamTransaction(hal);

    // ── Main Window & Structural Layout ──
    QMainWindow window;
    window.setWindowTitle("RTSA-X 实时频谱与信号分析仪");
    window.resize(1380, 800);
    window.setStyleSheet("QMainWindow { background-color: #0a0c14; }");

    auto* centralWidget = new QWidget(&window);
    auto* rootLayout    = new QVBoxLayout(centralWidget);
    rootLayout->setContentsMargins(0, 0, 0, 0);
    rootLayout->setSpacing(0);

    // 1. Top Instrumentation Status Bar
    auto* topBar = new rtsa::TopBarWidget(centralWidget);
    rootLayout->addWidget(topBar);

    // 2. Middle Content Area (Left: Plot + Waterfall, Right: Tabbed Analysis Sidebar)
    auto* contentArea   = new QWidget(centralWidget);
    auto* contentLayout = new QHBoxLayout(contentArea);
    contentLayout->setContentsMargins(0, 0, 0, 0);
    contentLayout->setSpacing(0);

    auto* leftContainer = new QWidget(contentArea);
    auto* leftLayout    = new QVBoxLayout(leftContainer);
    leftLayout->setContentsMargins(0, 0, 0, 0);
    leftLayout->setSpacing(0);

    auto* spectrumPlot = new rtsa::SpectrumPlot(leftContainer);
    spectrumPlot->setCenterFreq(2.4e9);
    spectrumPlot->setSpan(100e6);
    spectrumPlot->setRefLevel(0.0);
    spectrumPlot->setDbPerDiv(10.0);

    auto* spectrogramWidget = new rtsa::SpectrogramWidget(leftContainer);
    spectrogramWidget->setParams(2.4e9, 100e6, 0.0);
    spectrogramWidget->hide(); // Hidden by default

    leftLayout->addWidget(spectrumPlot, 3);
    leftLayout->addWidget(spectrogramWidget, 2);

    // Right Sidebar Tabbed Control Panel
    auto* controlPanel = new rtsa::ControlPanel(contentArea);

    contentLayout->addWidget(leftContainer, 1);
    contentLayout->addWidget(controlPanel, 0);
    rootLayout->addWidget(contentArea, 1);

    // 3. Bottom Bidirectional Parameter Interlock Bar
    auto* bottomParamBar = new rtsa::BottomParamBar(centralWidget);
    bottomParamBar->setCenterFreq(2.4e9);
    bottomParamBar->setSpan(100e6);
    bottomParamBar->setRefLevel(0.0);
    bottomParamBar->setScale(10.0);
    rootLayout->addWidget(bottomParamBar);

    window.setCentralWidget(centralWidget);

    // ── Create Data Processor (T2) ──
    auto* dataProcessor = new rtsa::DataProcessor(tripleBuffer, 4096);
    dataProcessor->setParams(2.4e9, 100e6);

    spectrumPlot->setMarkerEngine(&dataProcessor->markerEngine());

    // ── Single Frame Capture Helper ──
    static bool isSingleModeArmed = false;

    // Connect T2 -> UI
    QObject::connect(dataProcessor, &rtsa::DataProcessor::frameReady, [=](const rtsa::ProcessedFrame& frame) {
        if (fsmController->state() != rtsa::FsmState::Running && !isSingleModeArmed) {
            return;
        }

        spectrumPlot->onNewFrame(frame);
        spectrogramWidget->onNewFrame(frame);

        if (isSingleModeArmed) {
            isSingleModeArmed = false;
            fsmController->stop();
            topBar->setRunState(rtsa::RunState::Stopped);
            rtsa::Logger::info("Main", "单次采集完成，波形已冻结");
        }
    });

    // Marker updates -> SpectrumPlot Repaint
    QObject::connect(dataProcessor, &rtsa::DataProcessor::markersUpdated, [=]() {
        spectrumPlot->update();
    });

    // ── TopBar Run Controls ──
    QObject::connect(topBar, &rtsa::TopBarWidget::runRequested, [=]() {
        isSingleModeArmed = false;
        fsmController->startRunning();
        topBar->setRunState(rtsa::RunState::Running);
        rtsa::Logger::info("Main", "采集状态: 运行 (RUNNING)");
    });

    QObject::connect(topBar, &rtsa::TopBarWidget::singleRequested, [=]() {
        isSingleModeArmed = true;
        fsmController->startRunning();
        topBar->setRunState(rtsa::RunState::Single);
        rtsa::Logger::info("Main", "采集状态: 单次等待 (SINGLE ARMED)");
    });

    QObject::connect(topBar, &rtsa::TopBarWidget::stopRequested, [=]() {
        isSingleModeArmed = false;
        fsmController->stop();
        topBar->setRunState(rtsa::RunState::Stopped);
        rtsa::Logger::info("Main", "采集状态: 停止 (STOPPED)");
    });

    // ── Parameter Update Synchronizer Function ──
    auto applyParameters = [=](double centerHz, double spanHz, double refDbm) {
        paramTxn->setCenterFreq(centerHz);
        paramTxn->setSpan(spanHz);
        paramTxn->setRefLevel(refDbm);

        if (paramTxn->commit()) {
            spectrumPlot->setCenterFreq(centerHz);
            spectrumPlot->setSpan(spanHz);
            spectrumPlot->setRefLevel(refDbm);

            spectrogramWidget->setParams(centerHz, spanHz, refDbm);
            dataProcessor->setParams(centerHz, spanHz);

            bottomParamBar->setCenterFreq(centerHz);
            bottomParamBar->setSpan(spanHz);
            bottomParamBar->setRefLevel(refDbm);

            topBar->setRtbw(spanHz);
            topBar->setRbw(spanHz / 4096.0);
        }
    };

    // Initialize TopBar Stats
    topBar->setRtbw(100e6);
    topBar->setRbw(100e6 / 4096.0);
    topBar->setRunState(rtsa::RunState::Running);

    // ── Connect BottomParamBar ──
    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::centerFreqChanged, [=](double hz) {
        applyParameters(hz, spectrumPlot->span(), spectrumPlot->refLevel());
    });

    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::spanChanged, [=](double hz) {
        applyParameters(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
    });

    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::refLevelChanged, [=](double dBm) {
        applyParameters(spectrumPlot->centerFreq(), spectrumPlot->span(), dBm);
    });

    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::scaleChanged, [=](double dbPerDiv) {
        spectrumPlot->setDbPerDiv(dbPerDiv);
    });

    // ── Connect SpectrumPlot Drag & Zoom Shortcuts ──
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::centerFreqUserChanged, [=](double hz) {
        applyParameters(hz, spectrumPlot->span(), spectrumPlot->refLevel());
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::spanUserChanged, [=](double hz) {
        applyParameters(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::refLevelUserChanged, [=](double dBm) {
        applyParameters(spectrumPlot->centerFreq(), spectrumPlot->span(), dBm);
    });

    // ── Connect Trace Multi-Channel Toggles ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::traceToggled, [=](int traceIdx, bool enabled) {
        dataProcessor->setTraceEnabled(traceIdx, enabled);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::resetAllTracesRequested, [=]() {
        dataProcessor->resetAllTraces();
    });

    // ── Connect Marker Actions (Independent) ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::markerSelected, [=](int id) {
        if (!dataProcessor->markerEngine().marker(id).active) {
            dataProcessor->triggerPeakSearch(id);
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakSearchRequested, [=](int id) {
        dataProcessor->triggerPeakSearch(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::nextPeakRequested, [=](int id) {
        dataProcessor->triggerNextPeak(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakRightRequested, [=](int id) {
        dataProcessor->triggerNextPeakRight(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakLeftRequested, [=](int id) {
        dataProcessor->triggerNextPeakLeft(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::minSearchRequested, [=](int id) {
        dataProcessor->triggerMinSearch(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::continuousPeakToggled, [=](bool enabled, int markerId) {
        dataProcessor->setContinuousPeak(markerId, enabled);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::globalDeltaToggled, [=](bool enable, int refId) {
        dataProcessor->markerEngine().setGlobalDelta(enable, refId);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::clearAllMarkersRequested, [=]() {
        dataProcessor->markerEngine().setGlobalDelta(false, 1);
        for (int i = 1; i <= 6; ++i) {
            dataProcessor->markerEngine().setMarkerActive(i, false);
            dataProcessor->setContinuousPeak(i, false);
        }
        spectrumPlot->update();
    });

    // ── Full Span Shortcut Helper ──
    auto doFullSpan = [=]() {
        applyParameters(3005.0e6, 5990.0e6, spectrumPlot->refLevel());
        rtsa::Logger::info("Main", "激活全频跨度: 10 MHz ~ 6.0 GHz");
    };

    QObject::connect(controlPanel, &rtsa::ControlPanel::fullSpanRequested, doFullSpan);
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::fullSpanRequested, doFullSpan);

    // ── Screenshot Helper ──
    auto doSaveScreenshot = [&window]() {
        QDir exportDir("exports");
        if (!exportDir.exists()) {
            QDir().mkdir("exports");
        }
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString filename = QString("exports/screenshot_%1.png").arg(timestamp);

        QPixmap pixmap = window.grab();
        if (pixmap.save(filename)) {
            rtsa::Logger::info("Main", QString("屏幕截图已保存至 %1").arg(filename));
            QMessageBox::information(&window, "截图已保存",
                                     QString("当前屏幕截图已成功保存到:\n%1").arg(filename));
        } else {
            rtsa::Logger::error("Main", "保存截图失败");
            QMessageBox::warning(&window, "错误", "保存屏幕截图失败。");
        }
    };

    QObject::connect(controlPanel, &rtsa::ControlPanel::saveScreenshotRequested, doSaveScreenshot);
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::screenshotRequested, doSaveScreenshot);

    // ── Context Menu Actions in SpectrumPlot ──
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::peakSearchRequested, [=](int id) {
        dataProcessor->triggerPeakSearch(id);
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::resetTracesRequested, [=]() {
        dataProcessor->resetAllTraces();
    });

    // ── Spectrogram Toggle ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::spectrogramToggled, [spectrogramWidget](bool show) {
        if (show) spectrogramWidget->show();
        else spectrogramWidget->hide();
    });

    // ── CSV Trace Export ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::exportCsvRequested, [dataProcessor, spectrumPlot, &window]() {
        QDir exportDir("exports");
        if (!exportDir.exists()) {
            QDir().mkdir("exports");
        }
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString filename = QString("exports/trace_%1.csv").arg(timestamp);

        QFile file(filename);
        if (file.open(QIODevice::WriteOnly | QIODevice::Text)) {
            QTextStream out(&file);
            out << "Frequency_Hz,Amplitude_dBm\n";

            double centerFreq = spectrumPlot->centerFreq();
            double span = spectrumPlot->span();
            double startFreq = centerFreq - span / 2.0;

            std::vector<float> processeddBm = dataProcessor->currentSpectrumTrace();
            int count = static_cast<int>(processeddBm.size());

            if (count > 0) {
                for (int i = 0; i < count; ++i) {
                    double freq = startFreq + (static_cast<double>(i) / count) * span;
                    out << QString::number(freq, 'f', 2) << ","
                        << QString::number(processeddBm[i], 'f', 2) << "\n";
                }
            }

            file.close();
            rtsa::Logger::info("Main", QString("迹线 CSV 数据已导出至 %1 (%2 点)").arg(filename).arg(count));
            QMessageBox::information(&window, "CSV 导出完成",
                                     QString("迹线数据已成功导出至:\n%1\n(共 %2 点)").arg(filename).arg(count));
        }
    });

    // ── FPS Update Timer ──
    auto* fpsTimer = new QTimer();
    QObject::connect(fpsTimer, &QTimer::timeout, [spectrumPlot, topBar]() {
        topBar->setFps(spectrumPlot->currentFps());
    });
    fpsTimer->start(500);

    // ── Create T1 DMA Thread ──
    auto* dmaThread = new rtsa::DmaRecvThread(hal, tripleBuffer);

    // Start threads & FSM
    fsmController->startRunning();
    dataProcessor->start();
    dmaThread->start();

    window.show();
    rtsa::Logger::info("Main", "RTSA-X 实时信号分析仪运行中");

    int result = app.exec();

    // Clean Shutdown
    dmaThread->stopThread();
    dmaThread->wait(2000);

    dataProcessor->stopThread();
    dataProcessor->wait(2000);

    fpsTimer->stop();

    delete fpsTimer;
    delete dmaThread;
    delete dataProcessor;
    delete tripleBuffer;
    delete paramTxn;
    delete fsmController;
    delete mock;

    return result;
}

