                                     QString("Trace data successfully exported to:\n%1\n(%2 points)").arg(filename).arg(count));
        }
    });

    // ── FPS Update Timer ──
    auto* fpsTimer = new QTimer();
    QObject::connect(fpsTimer, &QTimer::timeout, [spectrumPlot, topBar]() {
        topBar->setFps(spectrumPlot->currentFps());
    });
    fpsTimer->start(500);

    // ── Create T1 DMA Thread ──
    auto* dmaThread = new rtsa::DmaRecvThread(hal, tripleBuffer);

    // Start threads & FSM
    fsmController->startRunning();
    dataProcessor->start();
    dmaThread->start();

    window.show();
    rtsa::Logger::info("Main", "Application running in V2.0 Keysight-style UI mode");

    int result = app.exec();

    // Clean Shutdown
    dmaThread->stopThread();
    dmaThread->wait(2000);

    dataProcessor->stopThread();
    dataProcessor->wait(2000);

    fpsTimer->stop();

    delete fpsTimer;
    delete dmaThread;
    delete dataProcessor;
    delete tripleBuffer;
    delete paramTxn;
    delete fsmController;
    delete mock;

    return result;
}

