void MarkerEngine::findLocalPeaks(const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    m_detectedPeaks.clear();
    if (!dBmArray || size < 10) return;

    double startFreq = centerFreqHz - spanHz / 2.0;

    // 1. Minimum peak separation distance (bins) to prevent multi-triggering on the same signal peak
    const int minPeakDist = std::max(25, size / 120);

    // 2. Simple local peak candidate detection with noise floor threshold
    struct Candidate {
        int bin;
        float amp;
    };
    std::vector<Candidate> candidates;

    for (int i = 2; i < size - 2; ++i) {
        float val = dBmArray[i];
        if (val > dBmArray[i - 1] && val > dBmArray[i - 2] &&
            val >= dBmArray[i + 1] && val > dBmArray[i + 2]) {
            candidates.push_back({i, val});
        }
    }

    if (candidates.empty()) return;

    // Sort candidates by amplitude descending
    std::sort(candidates.begin(), candidates.end(), [](const Candidate& a, const Candidate& b) {
        return a.amp > b.amp;
    });

    // 3. Non-Maximum Suppression (NMS) to extract true distinct peaks
    std::vector<bool> suppressed(candidates.size(), false);

    for (size_t i = 0; i < candidates.size(); ++i) {
        if (suppressed[i]) continue;

        LocalPeak peak;
        peak.binIndex  = candidates[i].bin;
        peak.amplitude = candidates[i].amp;
        peak.freqHz    = startFreq + (static_cast<double>(peak.binIndex) / size) * spanHz;
        m_detectedPeaks.push_back(peak);

        if (m_detectedPeaks.size() >= 20) break; // Keep top 20 distinct peaks

        // Suppress nearby candidates within minPeakDist
        for (size_t j = i + 1; j < candidates.size(); ++j) {
            if (!suppressed[j] && std::abs(candidates[j].bin - candidates[i].bin) < minPeakDist) {
                suppressed[j] = true;
            }
        }
    }
}

// Ultra-fast O(N) single-pass peak search (No findLocalPeaks overhead!)
void MarkerEngine::searchPeak(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (!dBmArray || size <= 0) return;

    int maxBin = 0;
    float maxVal = dBmArray[0];

    for (int i = 1; i < size; ++i) {
        if (dBmArray[i] > maxVal) {
            maxVal = dBmArray[i];
            maxBin = i;
        }
    }

    auto& m = marker(id);
    m.active = true;
    m.binIndex = maxBin;
    m.amplitude = maxVal;
    double startFreq = centerFreqHz - spanHz / 2.0;
    m.freqHz = startFreq + (static_cast<double>(maxBin) / size) * spanHz;
}

void MarkerEngine::searchNextPeak(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    findLocalPeaks(dBmArray, size, centerFreqHz, spanHz);

    auto& m = marker(id);
    m.active = true;

    if (m_detectedPeaks.empty()) {
        searchPeak(id, dBmArray, size, centerFreqHz, spanHz);
        return;
    }

    if (m_detectedPeaks.size() == 1) {
        m.binIndex  = m_detectedPeaks[0].binIndex;
        m.amplitude = m_detectedPeaks[0].amplitude;
        m.freqHz    = m_detectedPeaks[0].freqHz;
        return;
    }

    // Find which peak in m_detectedPeaks the marker is currently closest to
    int currentPeakRank = -1;
    const int matchTolerance = std::max(20, size / 150);

    for (size_t i = 0; i < m_detectedPeaks.size(); ++i) {
        if (std::abs(m_detectedPeaks[i].binIndex - m.binIndex) <= matchTolerance) {
            currentPeakRank = static_cast<int>(i);
            break;
        }
    }

    // Step to next rank in amplitude descending order (Rank 0 -> 1 -> 2 -> ... -> 0)
    int nextRank = (currentPeakRank >= 0) ? ((currentPeakRank + 1) % m_detectedPeaks.size()) : 1;
    if (nextRank >= static_cast<int>(m_detectedPeaks.size())) {
        nextRank = 0;
    }

    m.binIndex  = m_detectedPeaks[nextRank].binIndex;
    m.amplitude = m_detectedPeaks[nextRank].amplitude;
    m.freqHz    = m_detectedPeaks[nextRank].freqHz;
}

void MarkerEngine::searchNextPeakRight(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    findLocalPeaks(dBmArray, size, centerFreqHz, spanHz);

    auto& m = marker(id);
    m.active = true;

    const LocalPeak* bestRight = nullptr;
    double minRightDiff = 1e12;

    for (const auto& p : m_detectedPeaks) {
        if (p.binIndex > m.binIndex + 10) {
            double diff = p.freqHz - m.freqHz;
            if (diff > 0 && diff < minRightDiff) {
                minRightDiff = diff;
                bestRight = &p;
            }
        }
    }

    if (bestRight) {
        m.binIndex  = bestRight->binIndex;
        m.amplitude = bestRight->amplitude;
        m.freqHz    = bestRight->freqHz;
    }
}

void MarkerEngine::searchNextPeakLeft(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    findLocalPeaks(dBmArray, size, centerFreqHz, spanHz);

    auto& m = marker(id);
    m.active = true;

    const LocalPeak* bestLeft = nullptr;
    double minLeftDiff = 1e12;

    for (const auto& p : m_detectedPeaks) {
        if (p.binIndex < m.binIndex - 10) {
            double diff = m.freqHz - p.freqHz;
            if (diff > 0 && diff < minLeftDiff) {
                minLeftDiff = diff;
                bestLeft = &p;
            }
        }
    }

    if (bestLeft) {
        m.binIndex  = bestLeft->binIndex;
        m.amplitude = bestLeft->amplitude;
        m.freqHz    = bestLeft->freqHz;
    }
}

