void ControlPanel::setupDisplayTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 12, 8, 8);
    layout->setSpacing(10);

    m_btnSpectrogramToggle = new QPushButton("瀑布图谱: 开启", tab);
    layout->addWidget(m_btnSpectrogramToggle);

    // Common SPAN Quick Select Section
    auto* lblSpanTitle = new QLabel("常用跨度 (SPAN):", tab);
    lblSpanTitle->setStyleSheet("color: #38bdf8; font-weight: bold; margin-top: 6px;");
    layout->addWidget(lblSpanTitle);

    auto* spanGrid = new QGridLayout();
    spanGrid->setSpacing(6);

    struct SpanPreset {
        const char* label;
        double hz;
    };
    static const SpanPreset presets[] = {
        {"10 MHz", 10.0e6},
        {"20 MHz", 20.0e6},
        {"50 MHz", 50.0e6},
        {"100 MHz", 100.0e6},
        {"200 MHz", 200.0e6},
        {"500 MHz", 500.0e6},
        {"1.0 GHz", 1000.0e6},
        {"全跨度 6G", 5990.0e6}
    };

    for (int i = 0; i < 8; ++i) {
        auto* btn = new QPushButton(presets[i].label, tab);
        btn->setStyleSheet("background-color: #1e2538; color: #dae2ed; padding: 4px; font-size: 12px;");
        double hz = presets[i].hz;
        connect(btn, &QPushButton::clicked, [this, hz, i]() {
            if (i == 7) {
                emit fullSpanRequested();
            } else {
                emit spanChanged(hz);
            }
        });
        spanGrid->addWidget(btn, i / 2, i % 2);
    }

    layout->addLayout(spanGrid);
    layout->addStretch(1);

    connect(m_btnSpectrogramToggle, &QPushButton::clicked, [this]() {
        m_isSpectrogramActive = !m_isSpectrogramActive;
        if (m_isSpectrogramActive) {
            m_btnSpectrogramToggle->setText("瀑布图谱: 关闭");
            m_btnSpectrogramToggle->setStyleSheet("background-color: #0284c7; color: #ffffff; border: 1px solid #38bdf8;");
        } else {
            m_btnSpectrogramToggle->setText("瀑布图谱: 开启");
            m_btnSpectrogramToggle->setStyleSheet("");
        }
        emit spectrogramToggled(m_isSpectrogramActive);
    });
}

