92: static void convertDbmToScreenPoints(const QVector<float>& dBmVec,
93:                                      const QRect& area,
94:                                      double refLevel,
95:                                      double totalRange,
96:                                      QVector<QPointF>& outPoints)
97: {
98:     const int count = dBmVec.size();
99:     if (count == 0 || area.width() <= 0 || area.height() <= 0) {
100:         outPoints.clear();
101:         return;
102:     }
103: 
104:     outPoints.clear();
105:     outPoints.reserve(count);
106: 
107:     auto mapY = [area, refLevel, totalRange](float val) -> double {
108:         double yNorm = (refLevel - static_cast<double>(val)) / totalRange;
109:         double y = area.top() + yNorm * area.height();
110:         return qBound(static_cast<double>(area.top()), y, static_cast<double>(area.bottom()));
111:     };
112: 
113:     // If decimated Min-Max buffer (pair per column)
114:     int numColumns = count / 2;
115:     if (count >= 2 && numColumns > 0) {
116:         const double xStep = static_cast<double>(area.width()) / std::max(1, numColumns - 1);
117: 
118:         for (int col = 0; col < numColumns; ++col) {
119:             double x = area.left() + col * xStep;
120:             float valMin = dBmVec[col * 2];
121:             float valMax = dBmVec[col * 2 + 1];
122: 
123:             double yTop    = mapY(valMax); // Higher dBm -> higher on screen (smaller Y)
124:             double yBottom = mapY(valMin); // Lower dBm  -> lower on screen (larger Y)
125: 
126:             outPoints.append(QPointF(x, yTop));
127:             outPoints.append(QPointF(x, yBottom));
128:         }
129:     } else {
130:         const double xStep = static_cast<double>(area.width()) / std::max(1, count - 1);
131:         for (int i = 0; i < count; ++i) {
132:             double x = area.left() + i * xStep;
133:             outPoints.append(QPointF(x, mapY(dBmVec[i])));
134:         }
135:     }
136: }
