419:         if (x < area.left() || x > area.right() || y < area.top() || y > area.bottom()) continue;
420: 
421:         int xBucket = static_cast<int>(x / 24);
422:         int overlapIndex = xBucketCount[xBucket]++;
423:         double yOffset = overlapIndex * 20.0;
424: 
425:         // Inverted triangle marker
