void ControlPanel::setupMarkerTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 12, 8, 8);
    layout->setSpacing(8);

    // Marker Selection
    auto* rowSelect = new QHBoxLayout();
    auto* lblSelect = new QLabel("选择标记:", tab);
    m_markerSelectCombo = new QComboBox(tab);
    for (int i = 1; i <= 6; ++i) {
        m_markerSelectCombo->addItem(QString("标记 %1 (M%1)").arg(i), i);
    }
    rowSelect->addWidget(lblSelect);
    rowSelect->addWidget(m_markerSelectCombo, 1);
    layout->addLayout(rowSelect);

    // Peak Search Actions
    m_btnPeakSearch = new QPushButton("🎯 峰值搜索 (Peak)", tab);
    m_btnNextPeak   = new QPushButton("次峰搜索 (Next)", tab);

    auto* rowPeakLR = new QHBoxLayout();
    m_btnPeakLeft   = new QPushButton("◀ 左侧峰值", tab);
    m_btnPeakRight  = new QPushButton("右侧峰值 ▶", tab);
    rowPeakLR->addWidget(m_btnPeakLeft);
    rowPeakLR->addWidget(m_btnPeakRight);

    m_btnMinSearch  = new QPushButton("谷值搜索 (Min)", tab);

    layout->addWidget(m_btnPeakSearch);
    layout->addWidget(m_btnNextPeak);
    layout->addLayout(rowPeakLR);
    layout->addWidget(m_btnMinSearch);

    // Helper to update Continuous Peak button appearance
    auto updateContBtnStyle = [this](int markerId) {
        bool isActive = m_markerContinuousPeak[markerId - 1];
        if (isActive) {
            m_btnContinuousPeak->setText(QString("连续峰值跟踪: 开启 [M%1]").arg(markerId));
            m_btnContinuousPeak->setStyleSheet("background-color: #059669; color: #ffffff; border: 1px solid #10b981;");
        } else {
            m_btnContinuousPeak->setText(QString("连续峰值跟踪: 关闭 [M%1]").arg(markerId));
            m_btnContinuousPeak->setStyleSheet("");
        }
    };

    // Toggle Modes (Independent per Marker)
    m_btnContinuousPeak = new QPushButton("连续峰值跟踪: 关闭 [M1]", tab);
    m_btnDeltaToggle    = new QPushButton("差值标记 (Δ): 关闭", tab);
    m_btnClearMarkers   = new QPushButton("清空所有标记", tab);
    m_btnClearMarkers->setStyleSheet("color: #ef4444; border-color: #7f1d1d;");

    layout->addWidget(m_btnContinuousPeak);
    layout->addWidget(m_btnDeltaToggle);
    layout->addWidget(m_btnClearMarkers);

    layout->addStretch(1);

    // Marker Selection Changed -> Sync Continuous Peak button
    connect(m_markerSelectCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [=](int index) {
        int markerId = index + 1;
        updateContBtnStyle(markerId);
        emit markerSelected(markerId);
    });

    connect(m_btnPeakSearch, &QPushButton::clicked, [this]() {
        emit peakSearchRequested(m_markerSelectCombo->currentData().toInt());
    });

    connect(m_btnNextPeak, &QPushButton::clicked, [this]() {
        emit nextPeakRequested(m_markerSelectCombo->currentData().toInt());
    });

    connect(m_btnPeakLeft, &QPushButton::clicked, [this]() {
        emit peakLeftRequested(m_markerSelectCombo->currentData().toInt());
    });

    connect(m_btnPeakRight, &QPushButton::clicked, [this]() {
        emit peakRightRequested(m_markerSelectCombo->currentData().toInt());
    });

    connect(m_btnMinSearch, &QPushButton::clicked, [this]() {
        emit minSearchRequested(m_markerSelectCombo->currentData().toInt());
    });

    // Independent Continuous Peak Toggle
    connect(m_btnContinuousPeak, &QPushButton::clicked, [=]() {
        int markerId = m_markerSelectCombo->currentData().toInt();
        m_markerContinuousPeak[markerId - 1] = !m_markerContinuousPeak[markerId - 1];
        updateContBtnStyle(markerId);
        emit continuousPeakToggled(m_markerContinuousPeak[markerId - 1], markerId);
    });

    connect(m_btnDeltaToggle, &QPushButton::clicked, [this]() {
        m_isDeltaActive = !m_isDeltaActive;
        if (m_isDeltaActive) {
            m_btnDeltaToggle->setText("差值标记 (Δ): 开启");
            m_btnDeltaToggle->setStyleSheet("background-color: #0284c7; color: #ffffff; border: 1px solid #38bdf8;");
        } else {
            m_btnDeltaToggle->setText("差值标记 (Δ): 关闭");
            m_btnDeltaToggle->setStyleSheet("");
        }
        int refId = m_markerSelectCombo->currentData().toInt();
        emit globalDeltaToggled(m_isDeltaActive, refId);
    });

    connect(m_btnClearMarkers, &QPushButton::clicked, [this]() {
        for (int i = 0; i < 6; ++i) {
            m_markerContinuousPeak[i] = false;
        }
        int currentId = m_markerSelectCombo->currentData().toInt();
        m_btnContinuousPeak->setText(QString("连续峰值跟踪: 关闭 [M%1]").arg(currentId));
        m_btnContinuousPeak->setStyleSheet("");

        m_isDeltaActive = false;
        m_btnDeltaToggle->setText("差值标记 (Δ): 关闭");
        m_btnDeltaToggle->setStyleSheet("");
        emit clearAllMarkersRequested();
    });
}

void ControlPanel::setupTraceTab(QWidget* tab)
{
    auto* layout = new QVBoxLayout(tab);
    layout->setContentsMargins(8, 12, 8, 8);
    layout->setSpacing(10);

    auto* lblDesc = new QLabel("多通道叠加显示:", tab);
    lblDesc->setStyleSheet("color: #38bdf8; font-weight: bold;");
    layout->addWidget(lblDesc);

    // Multi-Trace Checkboxes with distinct color accents
    m_chkTrace1 = new QCheckBox("迹线 1: 实时 (刷新)", tab);
    m_chkTrace2 = new QCheckBox("迹线 2: 最大保持", tab);
    m_chkTrace3 = new QCheckBox("迹线 3: 最小保持", tab);
    m_chkTrace4 = new QCheckBox("迹线 4: 平均 (16次)", tab);

    m_chkTrace1->setStyleSheet("color: #00e5ff;");
    m_chkTrace2->setStyleSheet("color: #ffb300;");
    m_chkTrace3->setStyleSheet("color: #c084fc;");
    m_chkTrace4->setStyleSheet("color: #38bdf8;");

    m_chkTrace1->setChecked(true); // Trace 1 Live ON by default

    m_btnResetTraces = new QPushButton("重置所有迹线", tab);
    m_btnResetTraces->setStyleSheet("background-color: #334155; color: #f8fafc;");

    layout->addWidget(m_chkTrace1);
    layout->addWidget(m_chkTrace2);
    layout->addWidget(m_chkTrace3);
    layout->addWidget(m_chkTrace4);
    layout->addSpacing(8);
    layout->addWidget(m_btnResetTraces);

    layout->addStretch(1);

    connect(m_chkTrace1, &QCheckBox::toggled, [this](bool checked) { emit traceToggled(1, checked); });
    connect(m_chkTrace2, &QCheckBox::toggled, [this](bool checked) { emit traceToggled(2, checked); });
    connect(m_chkTrace3, &QCheckBox::toggled, [this](bool checked) { emit traceToggled(3, checked); });
    connect(m_chkTrace4, &QCheckBox::toggled, [this](bool checked) { emit traceToggled(4, checked); });

    connect(m_btnResetTraces, &QPushButton::clicked, this, &ControlPanel::resetAllTracesRequested);
}

